import React, { useState, useEffect, useMemo } from 'react';
import { useForm } from 'react-hook-form';
import { zodResolver } from '@hookform/resolvers/zod';
import * as z from 'zod';
import { Card, CardContent, CardHeader, CardTitle, CardDescription } from '@/components/ui/card';
import { Button } from '@/components/ui/button';
import { Input } from '@/components/ui/input';
import { Form, FormControl, FormField, FormItem, FormLabel, FormMessage } from '@/components/ui/form';
import { Select, SelectContent, SelectItem, SelectTrigger, SelectValue } from '@/components/ui/select';
import { Textarea } from '@/components/ui/textarea';
import { supabase } from '@/integrations/supabase/client';
import { showSuccess, showError } from '@/utils/toast';
import { useQuery, useMutation, useQueryClient } from '@tanstack/react-query';
import { useSession } from '@/components/SessionContextProvider';
import { useCompany } from '@/components/CompanyContext';
import { Diagnostic } from '@/types/diagnostic';
import { DiagnosticQuestionnaire } from '@/types/diagnosticQuestionnaire';
import { ScoringScale } from '@/types/scoringScale';
import { Loader2, ArrowLeft, ArrowRight, Save, CheckCircle } from 'lucide-react';
import { Label } from '@/components/ui/label';
import DiagnosticQuestionForm from '@/components/DiagnosticQuestionForm';
import { questionResponseSchema, QuestionResponseFormData } from '@/types/questionResponse'; // Importar do novo arquivo

const AnswerDiagnosticQuestionnairePage: React.FC = () => {
  const queryClient = useQueryClient();
  const { user } = useSession();
  const { selectedCompany } = useCompany();

  const [selectedDiagnosticId, setSelectedDiagnosticId] = useState<string | undefined>(undefined);
  const [currentQuestionIndex, setCurrentQuestionIndex] = useState(0);
  const [isSubmitted, setIsSubmitted] = useState(false);

  // 1. Fetch all diagnostics for the selected company
  const { data: diagnostics, isLoading: isLoadingDiagnostics } = useQuery<Diagnostic[], Error>({
    queryKey: ['diagnosticsListForAnswer', user?.id, selectedCompany?.id],
    queryFn: async () => {
      if (!user?.id || !selectedCompany?.id) return [];
      const { data, error } = await supabase
        .from('diagnostics')
        .select('*, companies(name), pillars(description), pillar_blocks(name)')
        .eq('user_id', user.id)
        .eq('company_id', selectedCompany.id)
        .order('created_at', { ascending: false });
      if (error) throw error;
      return data;
    },
    enabled: !!user?.id && !!selectedCompany?.id,
  });

  // 2. Fetch all questionnaire entries for the selected diagnostic
  const { data: questionnaireEntries, isLoading: isLoadingQuestionnaireEntries, error: errorQuestionnaireEntries } = useQuery<DiagnosticQuestionnaire[], Error>({
    queryKey: ['diagnosticQuestionnaireEntries', user?.id, selectedCompany?.id, selectedDiagnosticId],
    queryFn: async () => {
      if (!user?.id || !selectedCompany?.id || !selectedDiagnosticId) return [];
      const { data, error } = await supabase
        .from('diagnostic_questionnaires')
        .select(`
          id,
          user_id,
          company_id,
          diagnostic_id,
          kpi_id,
          score_id,
          evidence,
          order_number,
          created_at,
          updated_at,
          kpis(question),
          scoring_scales(score, description)
        `)
        .eq('user_id', user.id)
        .eq('company_id', selectedCompany.id)
        .eq('diagnostic_id', selectedDiagnosticId)
        .order('order_number', { ascending: true }) // Ordenar por order_number
        .order('created_at', { ascending: true }); // Fallback order
      if (error) throw error;

      // Post-process data to ensure kpis and scoring_scales are single objects or null
      const processedData: DiagnosticQuestionnaire[] = data.map((item: any) => ({
        ...item,
        kpis: item.kpis
          ? (Array.isArray(item.kpis)
            ? (item.kpis.length > 0 ? item.kpis[0] : null)
            : item.kpis)
          : null,
        scoring_scales: item.scoring_scales
          ? (Array.isArray(item.scoring_scales)
            ? (item.scoring_scales.length > 0 ? item.scoring_scales[0] : null)
            : item.scoring_scales)
          : null,
      }));

      console.log("Questionnaire Entries fetched (AnswerDiagnosticQuestionnairePage):", processedData); // Log para depuração
      return processedData;
    },
    enabled: !!user?.id && !!selectedCompany?.id && !!selectedDiagnosticId,
  });

  // 3. Fetch scoring scales
  const { data: scoringScales, isLoading: isLoadingScoringScales } = useQuery<ScoringScale[], Error>({
    queryKey: ['scoringScalesListForAnswer', user?.id],
    queryFn: async () => {
      if (!user?.id) return [];
      const { data, error } = await supabase
        .from('scoring_scales')
        .select('*')
        .eq('user_id', user.id)
        .order('score', { ascending: true });
      if (error) throw error;
      return data;
    },
    enabled: !!user?.id,
  });

  // Current question being displayed
  const currentQuestionnaire = useMemo(() => {
    if (!questionnaireEntries || questionnaireEntries.length === 0) return null;
    return questionnaireEntries[currentQuestionIndex];
  }, [questionnaireEntries, currentQuestionIndex]);

  // Formulário para a pergunta atual
  const formMethods = useForm<QuestionResponseFormData>({
    resolver: zodResolver(questionResponseSchema),
    shouldUnregister: true,
    defaultValues: { // Inicializa com valores vazios
      score_id: '',
      evidence: '',
      order_number: 1, // Adicionado
    } as QuestionResponseFormData, // Adicionado type assertion aqui
  });

  // Use useEffect para resetar o formulário quando a pergunta atual mudar
  useEffect(() => {
    if (currentQuestionnaire) {
      formMethods.reset({
        score_id: currentQuestionnaire.score_id || '',
        evidence: currentQuestionnaire.evidence || '',
        order_number: currentQuestionnaire.order_number || 1, // Adicionado
      });
    } else {
      formMethods.reset({
        score_id: '',
        evidence: '',
        order_number: 1, // Adicionado
      });
    }
  }, [currentQuestionnaire, formMethods]); // Depende de currentQuestionnaire e formMethods

  const updateQuestionnaireMutation = useMutation({
    mutationFn: async (data: { id: string; score_id: string; evidence: string | null; order_number: number | null }) => { // Adicionado order_number
      if (!user?.id || !selectedCompany?.id) throw new Error("Usuário não autenticado ou empresa não selecionada.");
      const { error } = await supabase
        .from('diagnostic_questionnaires')
        .update({
          score_id: data.score_id,
          evidence: data.evidence,
          order_number: data.order_number, // Adicionado
          updated_at: new Date().toISOString(),
        })
        .eq('id', data.id)
        .eq('user_id', user.id)
        .eq('company_id', selectedCompany.id);
      if (error) {
        throw error;
      }
    },
    onSuccess: () => {
      // Invalida a query para garantir que os dados em cache estejam frescos para a próxima pergunta
      queryClient.invalidateQueries({ queryKey: ['diagnosticQuestionnaireEntries', user?.id, selectedCompany?.id, selectedDiagnosticId] });
    },
    onError: (error: Error) => {
      showError(`Erro ao salvar resposta: ${error.message}`);
    },
  });

  // Standalone function to save the current question's response
  const saveCurrentQuestion = async (): Promise<boolean> => {
    if (!currentQuestionnaire) {
      showError("Nenhuma pergunta selecionada para salvar.");
      return false;
    }

    const isValid = await formMethods.trigger(); // Manually trigger validation
    if (!isValid) {
      showError("Por favor, preencha todos os campos obrigatórios.");
      return false;
    }

    const formData = formMethods.getValues();
    try {
      await updateQuestionnaireMutation.mutateAsync({
        id: currentQuestionnaire.id,
        score_id: formData.score_id || '', // Ensure it's a string
        evidence: formData.evidence || null,
        order_number: formData.order_number || null, // Adicionado
      });
      showSuccess('Resposta salva com sucesso!');
      return true;
    } catch (error) {
      // Error already handled by onError of mutation
      return false;
    }
  };

  const handleNextQuestion = async () => {
    const savedSuccessfully = await saveCurrentQuestion();
    if (savedSuccessfully) {
      if (questionnaireEntries && currentQuestionIndex < questionnaireEntries.length - 1) {
        setCurrentQuestionIndex(prev => prev + 1);
      } else {
        showSuccess("Você chegou ao final do questionário!");
        setIsSubmitted(true); // Marcar como concluído ao chegar ao final
      }
    }
  };

  const handlePreviousQuestion = async () => {
    const savedSuccessfully = await saveCurrentQuestion();
    if (savedSuccessfully) {
      if (currentQuestionIndex > 0) {
        setCurrentQuestionIndex(prev => prev - 1);
      }
    }
  };

  const handleSaveAll = async () => {
    const savedSuccessfully = await saveCurrentQuestion();
    if (savedSuccessfully) {
      showSuccess("Todas as respostas foram salvas!");
      setIsSubmitted(true);
    }
  };

  const isLoadingPage = isLoadingDiagnostics || isLoadingQuestionnaireEntries || isLoadingScoringScales;
  const isSaving = updateQuestionnaireMutation.isPending;

  const selectedDiagnosticDetails = diagnostics?.find(d => d.id === selectedDiagnosticId);

  if (!selectedCompany) {
    return (
      <div className="text-center text-muted-foreground py-8">
        Por favor, selecione uma empresa na barra lateral para responder o questionário de diagnóstico.
      </div>
    );
  }

  if (isLoadingPage) {
    return (
      <div className="flex items-center justify-center h-96">
        <Loader2 className="h-8 w-8 animate-spin text-sollux-red" />
        <span className="ml-2 text-muted-foreground">Carregando questionário...</span>
      </div>
    );
  }

  if (errorQuestionnaireEntries) {
    return <div className="text-center text-destructive">Erro ao carregar perguntas: {errorQuestionnaireEntries.message}</div>;
  }

  if (isSubmitted) {
    return (
      <div className="min-h-[calc(100vh-10rem)] flex items-center justify-center">
        <Card className="w-full max-w-md bg-card backdrop-blur-md rounded-2xl shadow-lg p-8 text-center border border-border">
          <CheckCircle className="h-16 w-16 text-green-500 mx-auto mb-4" />
          <h2 className="2xl font-bold text-foreground mb-2">Questionário Concluído!</h2>
          <p className="text-muted-foreground mb-6">
            Suas respostas foram salvas com sucesso.
          </p>
          <Button onClick={() => setIsSubmitted(false)} className="bg-sollux-red hover:bg-sollux-orange text-white rounded-lg">
            Voltar para o Questionário
          </Button>
        </Card>
      </div>
    );
  }

  return (
    <div className="space-y-6">
      <Card className="bg-card backdrop-blur-md border border-border shadow-lg rounded-2xl">
        <CardHeader>
          <CardTitle className="text-foreground uppercase font-bold">Responder Questionário de Diagnóstico</CardTitle>
          <CardDescription className="text-muted-foreground">
            Empresa: <span className="font-semibold">{selectedCompany.name}</span>
          </CardDescription>
        </CardHeader>
        <CardContent>
          <div className="mb-6">
            <Label className="text-foreground">Selecionar Diagnóstico</Label>
            <Select
              onValueChange={(value) => {
                setSelectedDiagnosticId(value === 'placeholder' ? undefined : value);
                setCurrentQuestionIndex(0); // Reset index when diagnostic changes
              }}
              value={selectedDiagnosticId || 'placeholder'} // Use 'placeholder' como valor quando nada está selecionado
              disabled={isLoadingDiagnostics || (diagnostics?.length || 0) === 0}
            >
              <SelectTrigger className="rounded-lg">
                <SelectValue placeholder="Selecione um diagnóstico para responder" />
              </SelectTrigger>
              <SelectContent>
                <SelectItem value="placeholder" disabled>Selecione um Diagnóstico</SelectItem> {/* Nova opção de placeholder */}
                {isLoadingDiagnostics ? (
                  <SelectItem value="loading" disabled>Carregando diagnósticos...</SelectItem>
                ) : (diagnostics?.length || 0) === 0 ? (
                  <SelectItem value="no-diagnostics" disabled>Nenhum diagnóstico cadastrado para esta empresa.</SelectItem>
                ) : (
                  diagnostics?.map((diagnostic) => (
                    diagnostic.id && diagnostic.id !== '' ? (
                      <SelectItem key={diagnostic.id} value={diagnostic.id}>
                        {diagnostic.id.substring(0, 8)}... ({diagnostic.pillars?.description || 'N/A'} / {diagnostic.pillar_blocks?.name || 'N/A'})
                      </SelectItem>
                    ) : null
                  ))
                )}
              </SelectContent>
            </Select>
            {!selectedDiagnosticId && (diagnostics?.length || 0) > 0 && (
              <p className="text-sm font-medium text-destructive mt-2">Por favor, selecione um diagnóstico para responder.</p>
            )}
            {(diagnostics?.length || 0) === 0 && (
              <p className="text-sm text-destructive mt-2">
                Nenhum diagnóstico encontrado para esta empresa. Crie um em "OPS | Diagnósticos" e adicione perguntas em "Gerenciar Perguntas do Diagnóstico" primeiro.
              </p>
            )}
          </div>

          {selectedDiagnosticId && questionnaireEntries && questionnaireEntries.length > 0 ? (
            <Card className="p-6 border border-border rounded-lg bg-muted/50">
              <CardHeader className="pb-4">
                <CardTitle className="text-xl font-bold text-foreground">
                  Pergunta {currentQuestionIndex + 1} de {questionnaireEntries.length}
                </CardTitle>
                <CardDescription className="text-muted-foreground">
                  Diagnóstico: {selectedDiagnosticDetails?.pillars?.description || 'N/A'} / {selectedDiagnosticDetails?.pillar_blocks?.name || 'N/A'}
                </CardDescription>
              </CardHeader>
              <CardContent>
                <Form {...formMethods}> {/* Passa o objeto formMethods para o Form */}
                  <form
                    key={currentQuestionnaire?.id || 'loading-question'} // A key no form é crucial
                    onSubmit={formMethods.handleSubmit(saveCurrentQuestion)}
                    className="space-y-6"
                  >
                    <DiagnosticQuestionForm
                      form={formMethods} // Passa o objeto formMethods como prop 'form'
                      currentQuestionnaire={currentQuestionnaire}
                      scoringScales={scoringScales}
                      isLoadingScoringScales={isLoadingScoringScales}
                      isSaving={isSaving}
                    />

                    <div className="flex justify-between gap-2 pt-4">
                      <Button
                        type="button"
                        variant="outline"
                        onClick={handlePreviousQuestion}
                        disabled={currentQuestionIndex === 0 || isSaving}
                        className="rounded-lg"
                      >
                        <ArrowLeft className="mr-2 h-4 w-4" /> Anterior
                      </Button>
                      <div className="flex gap-2">
                        <Button
                          type="submit"
                          disabled={isSaving}
                          className="rounded-lg bg-sollux-red hover:bg-sollux-orange"
                        >
                          {isSaving ? (
                            <>
                              <Loader2 className="mr-2 h-4 w-4 animate-spin" />
                              Salvando...
                            </>
                          ) : (
                            <>
                              <Save className="mr-2 h-4 w-4" /> Salvar
                            </>
                          )}
                        </Button>
                        <Button
                          type="button"
                          onClick={handleNextQuestion}
                          disabled={!questionnaireEntries || currentQuestionIndex === questionnaireEntries.length - 1 || isSaving}
                          className="rounded-lg bg-sollux-red hover:bg-sollux-orange"
                        >
                          Próximo <ArrowRight className="ml-2 h-4 w-4" />
                        </Button>
                      </div>
                    </div>
                    {questionnaireEntries && currentQuestionIndex === questionnaireEntries.length - 1 && (
                      <div className="text-center mt-4">
                        <Button
                          type="button"
                          onClick={handleSaveAll}
                          disabled={isSaving}
                          className="rounded-lg bg-green-600 hover:bg-green-700 text-white"
                        >
                          <CheckCircle className="mr-2 h-4 w-4" /> Concluir Questionário
                        </Button>
                      </div>
                    )}
                  </form>
                </Form>
              </CardContent>
            </Card>
          ) : (
            <p className="text-center text-muted-foreground py-8">
              Nenhuma pergunta encontrada para este diagnóstico. Adicione perguntas em "Gerenciar Perguntas do Diagnóstico".
            </p>
          )}
        </CardContent>
      </Card>
    </div>
  );
};

export default AnswerDiagnosticQuestionnairePage;

import React, { useState, useEffect, useMemo } from 'react';
import { useForm } from 'react-hook-form';
import { zodResolver } from '@hookform/resolvers/zod';
import * as z from 'zod';
import { Card, CardContent, CardHeader, CardTitle } from '@/components/ui/card';
import { Button } from '@/components/ui/button';
import { Input } from '@/components/ui/input';
import { Dialog, DialogContent, DialogHeader, DialogTitle, DialogFooter } from '@/components/ui/dialog';
import { Form, FormControl, FormField, FormItem, FormLabel, FormMessage } from '@/components/ui/form';
import { Table, TableBody, TableCell, TableHead, TableHeader, TableRow } from '@/components/ui/table';
import { Plus, Edit, Trash2, Palette, Award } from 'lucide-react';
import { supabase } from '@/integrations/supabase/client';
import { showSuccess, showError } from '@/utils/toast';
import { ClassificationScale, ClassificationScaleFormData } from '@/types/classificationScale';
import { Pillar } from '@/types/pillar';
import { PillarBlock } from '@/types/pillarBlock';
import { useQuery, useMutation, useQueryClient } from '@tanstack/react-query';
import { useSession } from '@/components/SessionContextProvider';
import { Select, SelectContent, SelectItem, SelectTrigger, SelectValue } from '@/components/ui/select';
import { Badge } from '@/components/ui/badge';

const formSchema = z.object({
  pillar_id: z.string().optional().nullable().transform(e => e === '' ? null : e),
  pillar_block_id: z.string().optional().nullable().transform(e => e === '' ? null : e),
  min_percentage: z.coerce.number().min(0, { message: 'Mínimo 0%' }).max(100, { message: 'Máximo 100%' }),
  max_percentage: z.coerce.number().min(0, { message: 'Mínimo 0%' }).max(100, { message: 'Máximo 100%' }),
  classification_label: z.string().min(1, { message: 'A classificação é obrigatória.' }),
  color_code: z.enum(['red', 'yellow', 'blue', 'green'], { required_error: 'A cor é obrigatória.' }),
}).refine(data => data.max_percentage >= data.min_percentage, {
  message: "O percentual máximo deve ser maior ou igual ao mínimo.",
  path: ["max_percentage"],
});

const ClassificationScaleManagementPage: React.FC = () => {
  const queryClient = useQueryClient();
  const { user } = useSession();
  const [isDialogOpen, setIsDialogOpen] = useState(false);
  const [editingScale, setEditingScale] = useState<ClassificationScale | null>(null);

  const form = useForm<ClassificationScaleFormData>({
    resolver: zodResolver(formSchema),
    defaultValues: {
      pillar_id: '',
      pillar_block_id: '',
      min_percentage: '',
      max_percentage: '',
      classification_label: '',
      color_code: 'blue', // Default color
    },
  });

  const selectedPillarId = form.watch('pillar_id');

  useEffect(() => {
    if (editingScale) {
      form.reset({
        pillar_id: editingScale.pillar_id || '',
        pillar_block_id: editingScale.pillar_block_id || '',
        min_percentage: editingScale.min_percentage,
        max_percentage: editingScale.max_percentage,
        classification_label: editingScale.classification_label,
        color_code: editingScale.color_code,
      });
    } else {
      form.reset({
        pillar_id: '',
        pillar_block_id: '',
        min_percentage: '',
        max_percentage: '',
        classification_label: '',
        color_code: 'blue',
      });
    }
  }, [editingScale, form, isDialogOpen]);

  const { data: classificationScales, isLoading: isLoadingScales, error: errorScales } = useQuery<ClassificationScale[], Error>({
    queryKey: ['classificationScales', user?.id],
    queryFn: async () => {
      if (!user?.id) return [];
      const { data, error } = await supabase
        .from('classification_scales')
        .select('*, pillars(description), pillar_blocks(name)')
        .eq('user_id', user.id)
        .order('min_percentage', { ascending: true });
      if (error) throw error;
      return data;
    },
    enabled: !!user?.id,
  });

  const { data: pillars, isLoading: isLoadingPillars } = useQuery<Pillar[], Error>({
    queryKey: ['pillarsListForClassification', user?.id],
    queryFn: async () => {
      if (!user?.id) return [];
      const { data, error } = await supabase
        .from('pillars')
        .select('*')
        .eq('user_id', user.id)
        .order('description', { ascending: true });
      if (error) throw error;
      return data;
    },
    enabled: !!user?.id,
  });

  const { data: pillarBlocks, isLoading: isLoadingPillarBlocks } = useQuery<PillarBlock[], Error>({
    queryKey: ['pillarBlocksListForClassification', user?.id],
    queryFn: async () => {
      if (!user?.id) return [];
      const { data, error } = await supabase
        .from('pillar_blocks')
        .select('*')
        .eq('user_id', user.id)
        .order('name', { ascending: true });
      if (error) throw error;
      return data;
    },
    enabled: !!user?.id,
  });

  const filteredPillarBlocks = useMemo(() => {
    if (!pillarBlocks || !selectedPillarId) return [];
    return pillarBlocks.filter(block => block.pillar_id === selectedPillarId);
  }, [pillarBlocks, selectedPillarId]);

  const mutationOptions = {
    onSuccess: () => {
      queryClient.invalidateQueries({ queryKey: ['classificationScales', user?.id] });
      setIsDialogOpen(false);
      setEditingScale(null);
    },
    onError: (error: Error) => {
      showError(`Erro: ${error.message}`);
    },
  };

  const createScaleMutation = useMutation({
    mutationFn: async (data: ClassificationScaleFormData) => {
      if (!user?.id) throw new Error("Usuário não autenticado.");
      const { data: newScale, error } = await supabase
        .from('classification_scales')
        .insert({
          user_id: user.id,
          pillar_id: data.pillar_id === '' ? null : data.pillar_id,
          pillar_block_id: data.pillar_block_id === '' ? null : data.pillar_block_id,
          min_percentage: Number(data.min_percentage),
          max_percentage: Number(data.max_percentage),
          classification_label: data.classification_label,
          color_code: data.color_code,
        })
        .select()
        .single();
      if (error) throw error;
      return newScale;
    },
    ...mutationOptions,
    onSuccess: () => {
      mutationOptions.onSuccess();
      showSuccess('Régua de Classificação criada com sucesso!');
    },
  });

  const updateScaleMutation = useMutation({
    mutationFn: async (data: ClassificationScaleFormData) => {
      if (!editingScale?.id) throw new Error("ID da régua de classificação está faltando.");
      if (!user?.id) throw new Error("Usuário não autenticado.");
      const { data: updatedScale, error } = await supabase
        .from('classification_scales')
        .update({
          pillar_id: data.pillar_id === '' ? null : data.pillar_id,
          pillar_block_id: data.pillar_block_id === '' ? null : data.pillar_block_id,
          min_percentage: Number(data.min_percentage),
          max_percentage: Number(data.max_percentage),
          classification_label: data.classification_label,
          color_code: data.color_code,
        })
        .eq('id', editingScale.id)
        .eq('user_id', user.id)
        .select()
        .single();
      if (error) throw error;
      return updatedScale;
    },
    ...mutationOptions,
    onSuccess: () => {
      mutationOptions.onSuccess();
      showSuccess('Régua de Classificação atualizada com sucesso!');
    },
  });

  const deleteScaleMutation = useMutation({
    mutationFn: async (id: string) => {
      if (!user?.id) throw new Error("Usuário não autenticado.");
      const { error, count } = await supabase
        .from('classification_scales')
        .delete()
        .eq('id', id)
        .eq('user_id', user.id);
      
      if (error) {
        throw error;
      }
      if (count === 0) {
        throw new Error("Régua de classificação não encontrada ou você não tem permissão para excluí-la.");
      }
    },
    ...mutationOptions,
    onSuccess: () => {
      mutationOptions.onSuccess();
      showSuccess('Régua de Classificação excluída com sucesso!');
    },
  });

  const onSubmit = (data: ClassificationScaleFormData) => {
    if (editingScale) {
      updateScaleMutation.mutate(data);
    } else {
      createScaleMutation.mutate(data);
    }
  };

  const handleAddClick = () => {
    setEditingScale(null);
    setIsDialogOpen(true);
  };

  const handleEditClick = (scale: ClassificationScale) => {
    setEditingScale(scale);
    setIsDialogOpen(true);
  };

  const handleDeleteClick = (id: string) => {
    if (window.confirm('Tem certeza que deseja excluir esta régua de classificação?')) {
      deleteScaleMutation.mutate(id);
    }
  };

  const isMutating = createScaleMutation.isPending || updateScaleMutation.isPending || deleteScaleMutation.isPending;
  const isLoadingPage = isLoadingScales || isLoadingPillars || isLoadingPillarBlocks;

  const getColorClass = (colorCode: 'red' | 'yellow' | 'blue' | 'green') => {
    switch (colorCode) {
      case 'red': return 'bg-red-500 text-white';
      case 'yellow': return 'bg-yellow-500 text-black';
      case 'blue': return 'bg-blue-500 text-white';
      case 'green': return 'bg-green-500 text-white';
      default: return 'bg-gray-500 text-white';
    }
  };

  if (isLoadingPage) {
    return <div className="text-center text-muted-foreground">Carregando réguas de classificação...</div>;
  }

  if (errorScales) {
    return <div className="text-center text-destructive">Erro ao carregar réguas de classificação: {errorScales.message}</div>;
  }

  return (
    <div className="space-y-6">
      <Card className="bg-card backdrop-blur-md border border-border shadow-lg rounded-2xl">
        <CardHeader className="flex flex-row items-center justify-between">
          <CardTitle className="text-foreground uppercase font-bold">Gerenciar Régua de Classificação</CardTitle>
          <Button onClick={handleAddClick} className="bg-sollux-red hover:bg-sollux-red/90 text-white rounded-lg">
            <Plus className="mr-2 h-4 w-4" /> Adicionar Régua
          </Button>
        </CardHeader>
        <CardContent>
          <Table>
            <TableHeader>
              <TableRow>
                <TableHead className="text-foreground">Pilar</TableHead>
                <TableHead className="text-foreground">Bloco</TableHead>
                <TableHead className="text-foreground">Percentual</TableHead>
                <TableHead className="text-foreground">Classificação</TableHead>
                <TableHead className="text-foreground">Cor</TableHead>
                <TableHead className="text-right text-foreground">Ações</TableHead>
              </TableRow>
            </TableHeader>
            <TableBody>
              {classificationScales?.length === 0 ? (
                <TableRow>
                  <TableCell colSpan={6} className="text-center text-muted-foreground">
                    Nenhuma régua de classificação encontrada.
                  </TableCell>
                </TableRow>
              ) : (
                classificationScales?.map((scale) => (
                  <TableRow key={scale.id}>
                    <TableCell className="text-muted-foreground">{(scale as any).pillars?.description || 'Global'}</TableCell>
                    <TableCell className="text-muted-foreground">{(scale as any).pillar_blocks?.name || 'Global'}</TableCell>
                    <TableCell className="font-medium text-foreground">{scale.min_percentage}% a {scale.max_percentage}%</TableCell>
                    <TableCell className="text-muted-foreground">{scale.classification_label}</TableCell>
                    <TableCell>
                      <Badge className={getColorClass(scale.color_code)}>
                        {scale.color_code.charAt(0).toUpperCase() + scale.color_code.slice(1)}
                      </Badge>
                    </TableCell>
                    <TableCell className="text-right">
                      <Button
                        variant="ghost"
                        size="sm"
                        onClick={() => handleEditClick(scale)}
                        className="mr-2 text-foreground hover:bg-accent rounded-lg"
                        disabled={isMutating}
                      >
                        <Edit className="h-4 w-4" />
                      </Button>
                      <Button
                        variant="destructive"
                        size="sm"
                        onClick={() => handleDeleteClick(scale.id)}
                        className="bg-sollux-red hover:bg-red-700 text-white rounded-lg"
                        disabled={isMutating}
                      >
                        <Trash2 className="h-4 w-4" />
                      </Button>
                    </TableCell>
                  </TableRow>
                ))
              )}
            </TableBody>
          </Table>
        </CardContent>
      </Card>

      <Dialog open={isDialogOpen} onOpenChange={setIsDialogOpen}>
        <DialogContent className="sm:max-w-lg bg-card backdrop-blur-md rounded-2xl shadow-lg border border-border">
          <DialogHeader>
            <DialogTitle className="text-foreground">{editingScale ? 'Editar Régua de Classificação' : 'Adicionar Nova Régua de Classificação'}</DialogTitle>
          </DialogHeader>
          <Form {...form}>
            <form onSubmit={form.handleSubmit(onSubmit)} className="space-y-4">
              <div className="grid grid-cols-1 md:grid-cols-2 gap-4">
                <FormField
                  control={form.control}
                  name="pillar_id"
                  render={({ field }) => (
                    <FormItem>
                      <FormLabel className="text-foreground">Pilar (Opcional)</FormLabel>
                      <Select onValueChange={(value) => {
                        field.onChange(value === 'null-option' ? '' : value); // Pass '' to form, which then transforms to null
                        form.setValue('pillar_block_id', ''); // Reset pillar block when pillar changes
                      }} value={field.value || ''} disabled={isLoadingPillars}>
                        <FormControl>
                          <SelectTrigger className="rounded-lg">
                            <SelectValue placeholder="Global (todos os pilares)" />
                          </SelectTrigger>
                        </FormControl>
                        <SelectContent>
                          <SelectItem value="null-option">Global (todos os pilares)</SelectItem>
                          {pillars?.length === 0 ? (
                            <SelectItem value="no-pillars" disabled>Nenhum pilar cadastrado</SelectItem>
                          ) : (
                            pillars?.map((pillar) => (
                              pillar.id && pillar.id !== '' ? (
                                <SelectItem key={pillar.id} value={pillar.id}>
                                  {pillar.description}
                                </SelectItem>
                              ) : null
                            ))
                          )}
                        </SelectContent>
                      </Select>
                      <FormMessage />
                    </FormItem>
                  )}
                />
                <FormField
                  control={form.control}
                  name="pillar_block_id"
                  render={({ field }) => (
                    <FormItem>
                      <FormLabel className="text-foreground">Bloco (Opcional)</FormLabel>
                      <Select onValueChange={(value) => field.onChange(value === 'null-option' ? '' : value)} value={field.value || ''} disabled={!selectedPillarId || isLoadingPillarBlocks || filteredPillarBlocks.length === 0}>
                        <FormControl>
                          <SelectTrigger className="rounded-lg">
                            <SelectValue placeholder="Global (todos os blocos)" />
                          </SelectTrigger>
                        </FormControl>
                        <SelectContent>
                          <SelectItem value="null-option">Global (todos os blocos)</SelectItem>
                          {filteredPillarBlocks.length === 0 ? (
                            <SelectItem value="no-blocks" disabled>Nenhum bloco para este pilar</SelectItem>
                          ) : (
                            filteredPillarBlocks.map((block) => (
                              block.id && block.id !== '' ? (
                                <SelectItem key={block.id} value={block.id}>
                                  {block.name}
                                </SelectItem>
                              ) : null
                            ))
                          )}
                        </SelectContent>
                      </Select>
                      <FormMessage />
                    </FormItem>
                  )}
                />
              </div>
              <div className="grid grid-cols-1 md:grid-cols-2 gap-4">
                <FormField
                  control={form.control}
                  name="min_percentage"
                  render={({ field }) => (
                    <FormItem>
                      <FormLabel className="text-foreground">Percentual Mínimo (%)</FormLabel>
                      <FormControl>
                        <Input type="number" step="0.01" placeholder="Ex: 0" {...field} className="rounded-lg" />
                      </FormControl>
                      <FormMessage />
                    </FormItem>
                  )}
                />
                <FormField
                  control={form.control}
                  name="max_percentage"
                  render={({ field }) => (
                    <FormItem>
                      <FormLabel className="text-foreground">Percentual Máximo (%)</FormLabel>
                      <FormControl>
                        <Input type="number" step="0.01" placeholder="Ex: 49.99" {...field} className="rounded-lg" />
                      </FormControl>
                      <FormMessage />
                    </FormItem>
                  )}
                />
              </div>
              <FormField
                control={form.control}
                name="classification_label"
                render={({ field }) => (
                  <FormItem>
                    <FormLabel className="text-foreground">Classificação</FormLabel>
                    <FormControl>
                      <Input placeholder="Ex: Crítico, Alerta, Satisfatório" {...field} className="rounded-lg" />
                    </FormControl>
                    <FormMessage />
                  </FormItem>
                )}
              />
              <FormField
                control={form.control}
                name="color_code"
                render={({ field }) => (
                  <FormItem>
                    <FormLabel className="text-foreground">Cor da Sinalização</FormLabel>
                    <Select onValueChange={field.onChange} value={field.value} disabled={isMutating}>
                      <FormControl>
                        <SelectTrigger className="rounded-lg">
                          <SelectValue placeholder="Selecione uma cor" />
                        </SelectTrigger>
                      </FormControl>
                      <SelectContent>
                        <SelectItem value="red">Vermelho</SelectItem>
                        <SelectItem value="yellow">Amarelo</SelectItem>
                        <SelectItem value="blue">Azul</SelectItem>
                        <SelectItem value="green">Verde</SelectItem>
                      </SelectContent>
                    </Select>
                    <FormMessage />
                  </FormItem>
                )}
              />
              <DialogFooter className="flex justify-end gap-2 pt-4">
                <Button type="button" variant="outline" onClick={() => setIsDialogOpen(false)} disabled={isMutating} className="rounded-lg">
                  Cancelar
                </Button>
                <Button type="submit" disabled={isMutating} className="rounded-lg bg-sollux-red hover:bg-sollux-orange">
                  {editingScale ? 'Salvar Alterações' : 'Adicionar Régua'}
                </Button>
              </DialogFooter>
            </form>
          </Form>
        </DialogContent>
      </Dialog>
    </div>
  );
};

export default ClassificationScaleManagementPage;

import React, { useState, useEffect, useMemo } from 'react';
import { useForm } from 'react-hook-form';
import { zodResolver } from '@hookform/resolvers/zod';
import * as z from 'zod';
import { Card, CardContent, CardHeader, CardTitle, CardDescription } from '@/components/ui/card';
import { Button } from '@/components/ui/button';
import { Input } from '@/components/ui/input';
import { Form, FormControl, FormField, FormItem, FormLabel, FormMessage } from '@/components/ui/form';
import { Select, SelectContent, SelectItem, SelectTrigger, SelectValue } from '@/components/ui/select';
import { Textarea } from '@/components/ui/textarea';
import { supabase } from '@/integrations/supabase/client';
import { showSuccess, showError } from '@/utils/toast';
import { useQuery, useMutation, useQueryClient } from '@tanstack/react-query';
import { useSession } from '@/components/SessionContextProvider';
import { useCompany } from '@/components/CompanyContext';
import { Diagnostic } from '@/types/diagnostic';
import { DiagnosticQuestionnaire } from '@/types/diagnosticQuestionnaire';
import { ScoringScale } from '@/types/scoringScale';
import { Pillar } from '@/types/pillar';
import { PillarBlock } from '@/types/pillarBlock';
import { ClassificationScale } from '@/types/classificationScale';
import { Loader2, Save, Award, CheckCircle, ChevronDown, ChevronUp } from 'lucide-react';
import { Label } from '@/components/ui/label';
import { Badge } from '@/components/ui/badge';
import ReactQuill from 'react-quill';
import 'react-quill/dist/quill.snow.css';

// Schema para o formulário de avaliação do consultor
const evaluationFormSchema = z.object({
  consultant_evaluation: z.string().optional(),
});

const DiagnosticEvaluationPage: React.FC = () => {
  const queryClient = useQueryClient();
  const { user } = useSession();
  const { selectedCompany } = useCompany();

  const [selectedPillarId, setSelectedPillarId] = useState<string | undefined>(undefined);
  const [expandedDiagnosticId, setExpandedDiagnosticId] = useState<string | undefined>(undefined); // Para expandir/colapsar a avaliação individual
  const [editorLoaded, setEditorLoaded] = useState(false);

  useEffect(() => {
    setEditorLoaded(true);
  }, []);

  const form = useForm<z.infer<typeof evaluationFormSchema>>({
    resolver: zodResolver(evaluationFormSchema),
    defaultValues: {
      consultant_evaluation: '',
    },
  });

  // Helper to classify a percentage based on classification scales
  const classifyPercentage = (
    percentage: number,
    scales: ClassificationScale[],
    pillarId: string | null,
    blockId: string | null
  ): ClassificationScale | null => {
    // First, try to find a specific scale for the block
    const specificBlockScale = scales.find(s =>
      s.pillar_id === pillarId && s.pillar_block_id === blockId &&
      percentage >= s.min_percentage && percentage <= s.max_percentage
    );
    if (specificBlockScale) return specificBlockScale;

    // Then, try to find a specific scale for the pillar (global for pillar, but not block)
    const specificPillarScale = scales.find(s =>
      s.pillar_id === pillarId && s.pillar_block_id === null &&
      percentage >= s.min_percentage && percentage <= s.max_percentage
    );
    if (specificPillarScale) return specificPillarScale;

    // Finally, try to find a global scale (null for both pillar and block)
    const globalScale = scales.find(s =>
      s.pillar_id === null && s.pillar_block_id === null &&
      percentage >= s.min_percentage && percentage <= s.max_percentage
    );
    if (globalScale) return globalScale;

    return null;
  };

  // NEW: Fetch distinct pillar_ids from diagnostics for the current company and user
  const { data: diagnosticPillarIds, isLoading: isLoadingDiagnosticPillarIds } = useQuery<Array<{ pillar_id: string }>, Error>({
    queryKey: ['diagnosticPillarIdsForEvaluation', user?.id, selectedCompany?.id],
    queryFn: async () => {
      if (!user?.id || !selectedCompany?.id) return [];
      const { data, error } = await supabase
        .from('diagnostics')
        .select('pillar_id')
        .eq('user_id', user.id)
        .eq('company_id', selectedCompany.id)
        .not('pillar_id', 'is', null); // Only get diagnostics with a pillar_id
      if (error) throw error;
      // Extract unique pillar_ids
      const uniquePillarIds = Array.from(new Set(data.map(d => d.pillar_id)));
      return uniquePillarIds.map(id => ({ pillar_id: id! })); // Map back to expected format
    },
    enabled: !!user?.id && !!selectedCompany?.id,
  });

  const uniquePillarIds = useMemo(() => {
    return diagnosticPillarIds?.map(d => d.pillar_id) || [];
  }, [diagnosticPillarIds]);

  // Fetch all pillars for the filter dropdown, now filtered by uniquePillarIds
  const { data: allPillars, isLoading: isLoadingAllPillars } = useQuery<Pillar[], Error>({
    queryKey: ['allPillarsForEvaluationFilter', user?.id, uniquePillarIds],
    queryFn: async () => {
      if (!user?.id || uniquePillarIds.length === 0) return [];
      const { data, error } = await supabase
        .from('pillars')
        .select('*')
        .in('id', uniquePillarIds) // Filter by pillars that have diagnostics
        .eq('user_id', user.id)
        .order('description', { ascending: true });
      if (error) throw error;
      return data;
    },
    enabled: !!user?.id && uniquePillarIds.length > 0 && !isLoadingDiagnosticPillarIds,
  });

  // Fetch diagnostics for the selected company and user, filtered by selectedPillarId
  const { data: diagnostics, isLoading: isLoadingDiagnostics } = useQuery<Diagnostic[], Error>({
    queryKey: ['diagnosticsListForEvaluation', user?.id, selectedCompany?.id, selectedPillarId],
    queryFn: async () => {
      if (!user?.id || !selectedCompany?.id || !selectedPillarId) return [];
      let query = supabase
        .from('diagnostics')
        .select('*, companies(name), pillars(description), pillar_blocks(name), diagnostic_statuses(description)')
        .eq('user_id', user.id)
        .eq('company_id', selectedCompany.id)
        .eq('pillar_id', selectedPillarId) // Filter by selected pillar
        .order('created_at', { ascending: false });
      const { data, error } = await query;
      if (error) throw error;
      return data;
    },
    enabled: !!user?.id && !!selectedCompany?.id && !!selectedPillarId,
  });

  // Fetch ALL questionnaire entries for ALL diagnostics under the selected pillar
  const { data: allPillarQuestionnaireEntries, isLoading: isLoadingAllPillarQuestionnaireEntries } = useQuery<DiagnosticQuestionnaire[], Error>({
    queryKey: ['allPillarQuestionnaireEntriesForEvaluation', user?.id, selectedCompany?.id, selectedPillarId],
    queryFn: async () => {
      if (!user?.id || !selectedCompany?.id || !selectedPillarId) return [];

      // First, get all diagnostic IDs for the selected pillar and company
      const { data: diagnosticIdsData, error: diagnosticIdsError } = await supabase
        .from('diagnostics')
        .select('id')
        .eq('user_id', user.id)
        .eq('company_id', selectedCompany.id)
        .eq('pillar_id', selectedPillarId);

      if (diagnosticIdsError) throw diagnosticIdsError;
      const diagnosticIds = diagnosticIdsData.map(d => d.id);

      if (diagnosticIds.length === 0) return [];

      // Then, fetch all questionnaire entries for these diagnostic IDs
      const { data, error } = await supabase
        .from('diagnostic_questionnaires')
        .select(`
          id,
          diagnostic_id,
          kpi_id,
          score_id,
          evidence,
          order_number,
          kpis(question, pillar_id, pillar_block_id),
          scoring_scales(score, description)
        `)
        .eq('user_id', user.id)
        .eq('company_id', selectedCompany.id)
        .in('diagnostic_id', diagnosticIds) // Fetch for all diagnostics in the pillar
        .order('order_number', { ascending: true })
        .order('created_at', { ascending: true });
      if (error) throw error;

      const processedData: DiagnosticQuestionnaire[] = data.map((item: any) => ({
        ...item,
        kpis: item.kpis
          ? (Array.isArray(item.kpis)
            ? (item.kpis.length > 0 ? item.kpis[0] : null)
            : item.kpis)
          : null,
        scoring_scales: item.scoring_scales
          ? (Array.isArray(item.scoring_scales)
            ? (item.scoring_scales.length > 0 ? item.scoring_scales[0] : null)
            : item.scoring_scales)
          : null,
      }));
      return processedData;
    },
    enabled: !!user?.id && !!selectedCompany?.id && !!selectedPillarId,
  });

  // Fetch all pillar blocks for the selected pillar to get weights
  const { data: pillarBlocks, isLoading: isLoadingPillarBlocks } = useQuery<PillarBlock[], Error>({
    queryKey: ['pillarBlocksForEvaluation', user?.id, selectedPillarId],
    queryFn: async () => {
      if (!user?.id || !selectedPillarId) return [];
      const { data, error } = await supabase
        .from('pillar_blocks')
        .select('*')
        .eq('user_id', user.id)
        .eq('pillar_id', selectedPillarId)
        .order('name', { ascending: true });
      if (error) throw error;
      return data;
    },
    enabled: !!user?.id && !!selectedPillarId,
  });

  // Fetch classification scales
  const { data: classificationScales, isLoading: isLoadingClassificationScales } = useQuery<ClassificationScale[], Error>({
    queryKey: ['classificationScalesForEvaluation', user?.id],
    queryFn: async () => {
      if (!user?.id) return [];
      const { data, error } = await supabase
        .from('classification_scales')
        .select('*, pillars(description), pillar_blocks(name)')
        .eq('user_id', user.id)
        .order('min_percentage', { ascending: true });
      if (error) throw error;
      return data;
    },
    enabled: !!user?.id,
  });

  // Update form with consultant_evaluation when expandedDiagnosticId changes
  useEffect(() => {
    if (expandedDiagnosticId && diagnostics) {
      const currentDiagnostic = diagnostics.find(d => d.id === expandedDiagnosticId);
      form.reset({
        consultant_evaluation: currentDiagnostic?.consultant_evaluation || '',
      });
    } else {
      form.reset({ consultant_evaluation: '' });
    }
  }, [expandedDiagnosticId, diagnostics, form]);

  const updateDiagnosticEvaluationMutation = useMutation({
    mutationFn: async (data: z.infer<typeof evaluationFormSchema>) => {
      if (!user?.id || !selectedCompany?.id || !expandedDiagnosticId) {
        throw new Error("Usuário não autenticado, empresa não selecionada ou diagnóstico não disponível.");
      }
      const { error } = await supabase
        .from('diagnostics')
        .update({
          consultant_evaluation: data.consultant_evaluation || null,
        })
        .eq('id', expandedDiagnosticId)
        .eq('user_id', user.id)
        .eq('company_id', selectedCompany.id);
      if (error) throw error;
    },
    onSuccess: () => {
      queryClient.invalidateQueries({ queryKey: ['diagnosticsListForEvaluation', user?.id, selectedCompany?.id, selectedPillarId] });
      showSuccess('Avaliação do consultor salva com sucesso!');
    },
    onError: (error: Error) => {
      showError(`Erro ao salvar avaliação: ${error.message}`);
    },
  });

  const onSubmit = (data: z.infer<typeof evaluationFormSchema>) => {
    updateDiagnosticEvaluationMutation.mutate(data);
  };

  const isLoadingPage = isLoadingDiagnosticPillarIds || isLoadingAllPillars || isLoadingDiagnostics || isLoadingAllPillarQuestionnaireEntries || isLoadingPillarBlocks || isLoadingClassificationScales;
  const isSaving = updateDiagnosticEvaluationMutation.isPending;

  const selectedPillarDetails = allPillars?.find(p => p.id === selectedPillarId);

  // --- Lógica de Cálculo de Indicadores (agora usando allPillarQuestionnaireEntries para o pilar) ---
  const { blockIndicators, pillarIndicator, overallClassification } = useMemo(() => {
    if (!selectedPillarId || !allPillarQuestionnaireEntries || !pillarBlocks || !classificationScales) {
      return { blockIndicators: {}, pillarIndicator: null, overallClassification: null };
    }

    const blockScores: { [blockId: string]: { totalScore: number; maxScore: number; questionCount: number } } = {};
    const blockWeights: { [blockId: string]: number } = {};

    // Initialize block scores and weights
    pillarBlocks.forEach(block => {
      blockScores[block.id] = { totalScore: 0, maxScore: 0, questionCount: 0 };
      blockWeights[block.id] = block.weight_percentage;
    });

    // Aggregate scores for each block from ALL questionnaire entries under the selected pillar
    allPillarQuestionnaireEntries.forEach(entry => {
      const blockId = entry.kpis?.pillar_block_id;
      const score = entry.scoring_scales?.score;

      if (blockId && score !== undefined && blockScores[blockId]) {
        blockScores[blockId].totalScore += score;
        blockScores[blockId].maxScore += 5; // Max score for one question is 5
        blockScores[blockId].questionCount += 1;
      }
    });

    const calculatedBlockIndicators: { [blockId: string]: { percentage: number; classification: ClassificationScale | null } } = {};
    let totalPillarWeightedScore = 0;
    let totalPillarWeight = 0;

    // Calculate percentage for each block and its classification
    Object.keys(blockScores).forEach(blockId => {
      const blockData = blockScores[blockId];
      const blockWeight = blockWeights[blockId] || 0;

      if (blockData.questionCount > 0) {
        const percentage = (blockData.totalScore / blockData.maxScore) * 100;
        calculatedBlockIndicators[blockId] = {
          percentage,
          classification: classifyPercentage(percentage, classificationScales, selectedPillarId, blockId),
        };
        totalPillarWeightedScore += (percentage * blockWeight);
        totalPillarWeight += blockWeight;
      } else {
        calculatedBlockIndicators[blockId] = {
          percentage: 0,
          classification: classifyPercentage(0, classificationScales, selectedPillarId, blockId),
        };
        totalPillarWeight += blockWeight;
      }
    });

    // Calculate overall pillar indicator
    const pillarOverallPercentage = totalPillarWeight > 0 ? (totalPillarWeightedScore / totalPillarWeight) : 0;
    const pillarOverallClassification = classifyPercentage(pillarOverallPercentage, classificationScales, selectedPillarId, null);

    return {
      blockIndicators: calculatedBlockIndicators,
      pillarIndicator: { percentage: pillarOverallPercentage, classification: pillarOverallClassification },
      overallClassification: pillarOverallClassification,
    };
  }, [selectedPillarId, allPillarQuestionnaireEntries, pillarBlocks, classificationScales, classifyPercentage]);

  const getColorClass = (colorCode: 'red' | 'yellow' | 'blue' | 'green' | undefined) => {
    switch (colorCode) {
      case 'red': return 'bg-red-500 text-white';
      case 'yellow': return 'bg-yellow-500 text-black';
      case 'blue': return 'bg-blue-500 text-white';
      case 'green': return 'bg-green-500 text-white';
      default: return 'bg-gray-500 text-white';
    }
  };

  if (!selectedCompany) {
    return (
      <div className="text-center text-muted-foreground py-8">
        Por favor, selecione uma empresa na barra lateral para realizar a avaliação do diagnóstico.
      </div>
    );
  }

  if (isLoadingPage) {
    return (
      <div className="flex items-center justify-center h-96">
        <Loader2 className="h-8 w-8 animate-spin text-sollux-red" />
        <span className="ml-2 text-muted-foreground">Carregando dados para avaliação...</span>
      </div>
    );
  }

  return (
    <div className="space-y-6">
      <Card className="bg-card backdrop-blur-md border border-border shadow-lg rounded-2xl">
        <CardHeader>
          <CardTitle className="text-foreground uppercase font-bold">Avaliação do Diagnóstico</CardTitle>
          <CardDescription className="text-muted-foreground">
            Empresa: <span className="font-semibold">{selectedCompany.name}</span>
          </CardDescription>
        </CardHeader>
        <CardContent>
          <div className="mb-6">
            <Label className="text-foreground">Selecionar Pilar</Label>
            <Select
              onValueChange={(value) => {
                setSelectedPillarId(value === 'placeholder' ? undefined : value);
                setExpandedDiagnosticId(undefined); // Collapse any open diagnostic when pillar changes
              }}
              value={selectedPillarId || 'placeholder'}
              disabled={isLoadingAllPillars || (allPillars?.length || 0) === 0}
            >
              <SelectTrigger className="rounded-lg">
                <SelectValue placeholder="Selecione um Pilar" />
              </SelectTrigger>
              <SelectContent>
                <SelectItem value="placeholder" disabled>Selecione um Pilar</SelectItem>
                {isLoadingAllPillars ? (
                  <SelectItem value="loading" disabled>Carregando pilares...</SelectItem>
                ) : (allPillars?.length || 0) === 0 ? (
                  <SelectItem value="no-pillars" disabled>Nenhum pilar com diagnóstico cadastrado para esta empresa.</SelectItem>
                ) : (
                  allPillars?.map((pillar) => (
                    pillar.id && pillar.id !== '' ? (
                      <SelectItem key={pillar.id} value={pillar.id}>
                        {pillar.description}
                      </SelectItem>
                    ) : null
                  ))
                )}
              </SelectContent>
            </Select>
            {!selectedPillarId && (allPillars?.length || 0) > 0 && (
              <p className="text-sm font-medium text-destructive mt-2">Por favor, selecione um pilar para avaliar.</p>
            )}
            {(allPillars?.length || 0) === 0 && (
              <p className="text-sm text-destructive mt-2">
                Nenhum pilar encontrado para esta empresa. Crie um em "OPS | Pilares" e associe-o a um diagnóstico primeiro.
              </p>
            )}
          </div>

          {selectedPillarId && selectedPillarDetails ? (
            <div className="space-y-6">
              <Card className="p-6 border border-border rounded-lg bg-muted/50">
                <CardTitle className="text-xl font-bold text-foreground mb-4">
                  Pilar: {selectedPillarDetails.description || 'N/A'}
                </CardTitle>

                {/* Indicador Final do Pilar */}
                {pillarIndicator && (
                  <div className="mb-6 p-4 bg-background rounded-lg border border-border">
                    <h3 className="text-lg font-semibold text-foreground mb-2 flex items-center gap-2">
                      <Award className="h-5 w-5 text-sollux-red" /> Indicador Final do Pilar
                    </h3>
                    <p className="text-2xl font-bold text-foreground">
                      {pillarIndicator.percentage.toFixed(2)}%
                      {pillarIndicator.classification && (
                        <Badge className={getColorClass(pillarIndicator.classification.color_code)} style={{ marginLeft: '10px' }}>
                          {pillarIndicator.classification.classification_label}
                        </Badge>
                      )}
                    </p>
                  </div>
                )}

                {/* Indicadores por Bloco */}
                <h3 className="text-lg font-semibold text-foreground mb-4">Indicadores por Bloco</h3>
                <div className="grid grid-cols-1 md:grid-cols-2 gap-4 mb-6">
                  {pillarBlocks?.map(block => {
                    const indicator = blockIndicators[block.id];
                    return (
                      <Card key={block.id} className="p-4 border border-border rounded-lg">
                        <h4 className="font-semibold text-foreground mb-2">{block.name} ({block.weight_percentage}%)</h4>
                        {indicator ? (
                          <p className="text-xl font-bold text-foreground">
                            {indicator.percentage.toFixed(2)}%
                            {indicator.classification && (
                              <Badge className={getColorClass(indicator.classification.color_code)} style={{ marginLeft: '10px' }}>
                                {indicator.classification.classification_label}
                              </Badge>
                            )}
                          </p>
                        ) : (
                          <p className="text-muted-foreground">N/A</p>
                        )}
                      </Card>
                    );
                  })}
                </div>
              </Card>

              {/* Lista de Diagnósticos Individuais */}
              <h3 className="text-lg font-semibold text-foreground mb-4">Diagnósticos neste Pilar</h3>
              {diagnostics && diagnostics.length > 0 ? (
                <div className="space-y-4">
                  {diagnostics.map(diagnostic => (
                    <Card key={diagnostic.id} className="p-4 border border-border rounded-lg bg-muted/50">
                      <div className="flex items-center justify-between">
                        <div>
                          <CardTitle className="text-lg font-bold text-foreground">
                            Diagnóstico: {diagnostic.pillar_blocks?.name || 'N/A'}
                          </CardTitle>
                          <CardDescription className="text-muted-foreground">
                            Status: {diagnostic.diagnostic_statuses?.description || 'N/A'}
                          </CardDescription>
                        </div>
                        <Button
                          variant="ghost"
                          onClick={() => setExpandedDiagnosticId(expandedDiagnosticId === diagnostic.id ? undefined : diagnostic.id)}
                          className="rounded-lg"
                        >
                          {expandedDiagnosticId === diagnostic.id ? <ChevronUp className="h-4 w-4 mr-2" /> : <ChevronDown className="h-4 w-4 mr-2" />}
                          {expandedDiagnosticId === diagnostic.id ? 'Fechar Avaliação' : 'Avaliar Diagnóstico'}
                        </Button>
                      </div>

                      {expandedDiagnosticId === diagnostic.id && (
                        <CardContent className="mt-6 border-t border-border pt-6">
                          <h4 className="text-md font-semibold text-foreground mb-4">Perguntas e Respostas do Usuário</h4>
                          {allPillarQuestionnaireEntries && allPillarQuestionnaireEntries.filter(entry => entry.diagnostic_id === diagnostic.id).length > 0 ? (
                            <div className="space-y-3 mb-6">
                              {allPillarQuestionnaireEntries.filter(entry => entry.diagnostic_id === diagnostic.id).map(entry => (
                                <Card key={entry.id} className="p-3 border border-border rounded-lg">
                                  <p className="font-semibold text-foreground mb-1">
                                    {entry.order_number}. {entry.kpis?.question || 'Pergunta não disponível'}
                                  </p>
                                  <p className="text-muted-foreground text-sm">
                                    Nota do Usuário: {entry.scoring_scales?.score !== undefined ? entry.scoring_scales.score : 'N/A'}
                                    {entry.scoring_scales?.description && ` (${entry.scoring_scales.description})`}
                                  </p>
                                  {entry.evidence && (
                                    <p className="text-muted-foreground text-sm mt-1">
                                      Evidência: {entry.evidence}
                                    </p>
                                  )}
                                </Card>
                              ))}
                            </div>
                          ) : (
                            <p className="text-center text-muted-foreground mb-6">Nenhuma pergunta respondida para este diagnóstico.</p>
                          )}

                          {/* Formulário de Avaliação do Consultor para ESTE diagnóstico */}
                          <Card className="p-6 border border-border rounded-lg bg-background">
                            <CardHeader className="pb-4">
                              <CardTitle className="text-xl font-bold text-foreground">Avaliação do Consultor</CardTitle>
                              <CardDescription className="text-muted-foreground">
                                Escreva sua avaliação final para este diagnóstico específico.
                              </CardDescription>
                            </CardHeader>
                            <CardContent>
                              <Form {...form}>
                                <form onSubmit={form.handleSubmit(onSubmit)} className="space-y-4">
                                  <FormField
                                    control={form.control}
                                    name="consultant_evaluation"
                                    render={({ field }) => (
                                      <FormItem>
                                        <FormLabel className="text-foreground">Avaliação</FormLabel>
                                        <FormControl>
                                          {editorLoaded ? (
                                            <ReactQuill
                                              theme="snow"
                                              value={field.value || ''}
                                              onChange={field.onChange}
                                              className="bg-card rounded-lg"
                                              modules={{
                                                toolbar: [
                                                  [{ 'header': [1, 2, false] }],
                                                  ['bold', 'italic', 'underline', 'strike', 'link'],
                                                  [{ 'list': 'ordered'}, { 'list': 'bullet' }],
                                                  [{ 'indent': '-1'}, { 'indent': '+1' }],
                                                  ['image', 'code-block'],
                                                  [{ 'color': [] }, { 'background': [] }],
                                                  ['clean']
                                                ],
                                              }}
                                            />
                                          ) : (
                                            <div className="h-[200px] w-full bg-muted rounded-lg flex items-center justify-center text-muted-foreground">
                                              Carregando editor de texto...
                                            </div>
                                          )}
                                        </FormControl>
                                        <FormMessage />
                                      </FormItem>
                                    )}
                                  />
                                  <div className="flex justify-end pt-4">
                                    <Button type="submit" disabled={isSaving} className="rounded-lg bg-sollux-red hover:bg-sollux-orange">
                                      {isSaving ? (
                                        <>
                                          <Loader2 className="mr-2 h-4 w-4 animate-spin" />
                                          Salvando...
                                        </>
                                      ) : (
                                        <>
                                          <Save className="mr-2 h-4 w-4" /> Salvar Avaliação
                                        </>
                                      )}
                                    </Button>
                                  </div>
                                </form>
                              </Form>
                            </CardContent>
                          </Card>
                        </CardContent>
                      )}
                    </Card>
                  ))}
                </div>
              ) : (
                <p className="text-center text-muted-foreground py-8">
                  Nenhum diagnóstico encontrado para o pilar selecionado.
                </p>
              )}
            </div>
          ) : (
            <p className="text-center text-muted-foreground py-8">
              Selecione um pilar acima para visualizar os indicadores e realizar as avaliações.
            </p>
          )}
        </CardContent>
      </Card>
    </div>
  );
};

export default DiagnosticEvaluationPage;

import React, { useState, useEffect, useMemo } from 'react';
import { useForm } from 'react-hook-form';
import { zodResolver } from '@hookform/resolvers/zod';
import * as z from 'zod';
import { Card, CardContent, CardHeader, CardTitle, CardDescription } from '@/components/ui/card';
import { Button } from '@/components/ui/button';
import { Input } from '@/components/ui/input';
import { Dialog, DialogContent, DialogHeader, DialogTitle, DialogFooter, DialogDescription } from '@/components/ui/dialog';
import { Form, FormControl, FormField, FormItem, FormLabel, FormMessage } from '@/components/ui/form';
import { Table, TableBody, TableCell, TableHead, TableHeader, TableRow } from '@/components/ui/table';
import { Plus, Edit, Trash2 } from 'lucide-react';
import { supabase } from '@/integrations/supabase/client';
import { showSuccess, showError } from '@/utils/toast';
import { DiagnosticQuestionnaire, DiagnosticQuestionnaireFormData } from '@/types/diagnosticQuestionnaire';
import { Diagnostic } from '@/types/diagnostic';
import { Kpi } from '@/types/kpi';
import { ScoringScale } from '@/types/scoringScale';
import { Pillar } from '@/types/pillar'; // Importar Pillar
import { DiagnosticStatus } from '@/types/diagnosticStatus'; // Importar DiagnosticStatus
import { useQuery, useMutation, useQueryClient } from '@tanstack/react-query';
import { useSession } from '@/components/SessionContextProvider';
import { useCompany } from '@/components/CompanyContext';
import { Select, SelectContent, SelectItem, SelectTrigger, SelectValue } from '@/components/ui/select';
import { Textarea } from '@/components/ui/textarea';
import { format } from 'date-fns';
import { ptBR } from 'date-fns/locale';
import AddMultipleDiagnosticQuestionsDialog from '@/components/AddMultipleDiagnosticQuestionsDialog';
import { Label } from '@/components/ui/label';

// Tipo específico para os dados de pilar do diagnóstico necessários para o filtro
interface DiagnosticPillarOnly {
  pillar_id: string | null;
}

// Removido formSchema e o formulário de pergunta única, pois serão substituídos pelo novo diálogo.

const DiagnosticQuestionnairePage: React.FC = () => {
  const queryClient = useQueryClient();
  const { user } = useSession();
  const { selectedCompany } = useCompany();
  const [isAddQuestionsDialogOpen, setIsAddQuestionsDialogOpen] = useState(false);
  const [isEditDialogOpen, setIsEditDialogOpen] = useState(false);
  const [editingQuestionnaire, setEditingQuestionnaire] = useState<DiagnosticQuestionnaire | null>(null);
  
  // Novos estados para os filtros
  const [selectedPillarFilter, setSelectedPillarFilter] = useState<string>('all');
  const [selectedDiagnosticStatusFilter, setSelectedDiagnosticStatusFilter] = useState<string>('all');

  const [selectedDiagnosticToAnswer, setSelectedDiagnosticToAnswer] = useState<string | undefined>(undefined);

  // Formulário para edição de UMA pergunta (o mesmo que antes, mas agora para edição)
  const editForm = useForm<DiagnosticQuestionnaireFormData>({
    resolver: zodResolver(z.object({
      diagnostic_id: z.string().min(1, { message: 'O diagnóstico é obrigatório.' }),
      kpi_id: z.string().min(1, { message: 'A pergunta (KPI) é obrigatória.' }),
      score_id: z.string().min(1, { message: 'A nota é obrigatória.' }),
      evidence: z.string().optional(),
      order_number: z.number().min(1, { message: 'O número de ordem é obrigatório.' }), // Adicionado
    })),
    defaultValues: {
      diagnostic_id: undefined,
      kpi_id: undefined,
      score_id: undefined,
      evidence: '',
      order_number: 1, // Adicionado
    },
  });

  const selectedDiagnosticIdForEdit = editForm.watch('diagnostic_id');

  useEffect(() => {
    if (editingQuestionnaire) {
      editForm.reset({
        diagnostic_id: editingQuestionnaire.diagnostic_id || undefined,
        kpi_id: editingQuestionnaire.kpi_id || undefined,
        score_id: editingQuestionnaire.score_id || undefined,
        evidence: editingQuestionnaire.evidence || '',
        order_number: editingQuestionnaire.order_number || 1, // Adicionado
      });
    } else {
      editForm.reset({
        diagnostic_id: undefined,
        kpi_id: undefined,
        score_id: undefined,
        evidence: '',
        order_number: 1, // Adicionado
      });
    }
  }, [editingQuestionnaire, editForm, isEditDialogOpen]);

  // 1. Fetch all diagnostic statuses for the filter dropdown
  const { data: allDiagnosticStatuses, isLoading: isLoadingAllDiagnosticStatuses } = useQuery<DiagnosticStatus[], Error>({
    queryKey: ['allDiagnosticStatusesListForQuestionnaire', user?.id],
    queryFn: async () => {
      if (!user?.id) return [];
      const { data, error } = await supabase
        .from('diagnostic_statuses')
        .select('*')
        .eq('user_id', user.id)
        .order('description', { ascending: true });
      if (error) throw error;
      return data;
    },
    enabled: !!user?.id,
  });

  // 2. Fetch diagnostics based on selected filters for the "Select Diagnostic" dropdown
  const { data: diagnostics, isLoading: isLoadingDiagnostics } = useQuery<Diagnostic[], Error>({
    queryKey: ['diagnosticsListForQuestionnaire', user?.id, selectedCompany?.id, selectedPillarFilter, selectedDiagnosticStatusFilter],
    queryFn: async () => {
      if (!user?.id || !selectedCompany?.id) return [];
      let query = supabase
        .from('diagnostics')
        .select('*, companies(name), pillars(description), pillar_blocks(name)')
        .eq('user_id', user.id)
        .eq('company_id', selectedCompany.id);
      
      if (selectedPillarFilter !== 'all') {
        query = query.eq('pillar_id', selectedPillarFilter);
      }
      if (selectedDiagnosticStatusFilter !== 'all') {
        query = query.eq('diagnostic_status_id', selectedDiagnosticStatusFilter);
      }

      query = query.order('created_at', { ascending: false });
      const { data, error } = await query;
      if (error) throw error;
      return data;
    },
    enabled: !!user?.id && !!selectedCompany?.id,
  });

  // Reset selected diagnostic when filters change
  useEffect(() => {
    if (diagnostics && diagnostics.length > 0) {
      if (!diagnostics.some(d => d.id === selectedDiagnosticToAnswer)) {
        setSelectedDiagnosticToAnswer(undefined);
      }
    } else {
      setSelectedDiagnosticToAnswer(undefined);
    }
  }, [selectedPillarFilter, selectedDiagnosticStatusFilter, diagnostics]);

  // NEW: Fetch all diagnostics for the current company and user (without applying the current filters)
  // This is to get the full set of pillars that have diagnostics for this company, to populate the pillar filter dropdown
  const { data: allCompanyDiagnostics, isLoading: isLoadingAllCompanyDiagnostics } = useQuery<DiagnosticPillarOnly[], Error>({
    queryKey: ['allCompanyDiagnosticsForPillarFilter', user?.id, selectedCompany?.id],
    queryFn: async () => {
      if (!user?.id || !selectedCompany?.id) return [];
      const { data, error } = await supabase
        .from('diagnostics')
        .select('pillar_id') // Only need pillar_id
        .eq('user_id', user.id)
        .eq('company_id', selectedCompany.id);
      if (error) throw error;
      return data;
    },
    enabled: !!user?.id && !!selectedCompany?.id,
  });

  const uniquePillarIdsInCompanyDiagnostics = useMemo(() => {
    if (!allCompanyDiagnostics) return [];
    const ids = new Set<string>();
    allCompanyDiagnostics.forEach(d => {
      if (d.pillar_id) {
        ids.add(d.pillar_id);
      }
    });
    return Array.from(ids);
  }, [allCompanyDiagnostics]);

  // Now fetch the actual Pillar objects for these IDs, for the filter dropdown
  const { data: availablePillarsForFilter, isLoading: isLoadingAvailablePillarsForFilter } = useQuery<Pillar[], Error>({
    queryKey: ['availablePillarsForFilter', user?.id, uniquePillarIdsInCompanyDiagnostics],
    queryFn: async () => {
      if (!user?.id || uniquePillarIdsInCompanyDiagnostics.length === 0) return [];
      const { data, error } = await supabase
        .from('pillars')
        .select('*')
        .in('id', uniquePillarIdsInCompanyDiagnostics)
        .eq('user_id', user.id)
        .order('description', { ascending: true });
      if (error) throw error;
      return data;
    },
    enabled: !!user?.id && uniquePillarIdsInCompanyDiagnostics.length > 0,
  });


  // 4. Fetch questionnaire entries for the selected diagnostic
  const { data: questionnaires, isLoading: isLoadingQuestionnaires, error: errorQuestionnaires } = useQuery<DiagnosticQuestionnaire[], Error>({
    queryKey: ['diagnosticQuestionnaires', user?.id, selectedCompany?.id, selectedDiagnosticToAnswer],
    queryFn: async () => {
      if (!user?.id || !selectedCompany?.id || !selectedDiagnosticToAnswer) return [];
      const { data, error } = await supabase
        .from('diagnostic_questionnaires')
        .select(`
          id,
          user_id,
          company_id,
          diagnostic_id,
          kpi_id,
          score_id,
          evidence,
          order_number,
          created_at,
          updated_at,
          diagnostics(
            id,
            companies(name),
            pillars(description),
            pillar_blocks(name)
          ),
          kpis(question),
          scoring_scales(score, description),
          profiles(first_name, last_name)
        `)
        .eq('user_id', user.id)
        .eq('company_id', selectedCompany.id)
        .eq('diagnostic_id', selectedDiagnosticToAnswer) // Filter by selected diagnostic
        .order('order_number', { ascending: true }) // Ordenar por order_number
        .order('created_at', { ascending: false }); // Fallback order
      if (error) throw error;

      const processedData: DiagnosticQuestionnaire[] = data.map((item: any) => ({
        ...item,
        diagnostics: item.diagnostics
          ? (Array.isArray(item.diagnostics)
            ? (item.diagnostics.length > 0 ? item.diagnostics[0] : null)
            : item.diagnostics)
          : null,
        kpis: item.kpis
          ? (Array.isArray(item.kpis)
            ? (item.kpis.length > 0 ? item.kpis[0] : null)
            : item.kpis)
          : null,
        scoring_scales: item.scoring_scales
          ? (Array.isArray(item.scoring_scales)
            ? (item.scoring_scales.length > 0 ? item.scoring_scales[0] : null)
            : item.scoring_scales)
          : null,
        profiles: item.profiles
          ? (Array.isArray(item.profiles)
            ? (item.profiles.length > 0 ? item.profiles[0] : null)
            : item.profiles)
          : null,
      }));

      console.log("Questionnaires fetched (DiagnosticQuestionnairePage):", processedData); // Log para depuração
      return processedData;
    },
    enabled: !!user?.id && !!selectedCompany?.id && !!selectedDiagnosticToAnswer, // Enable only when diagnostic is selected
  });

  const { data: kpis, isLoading: isLoadingKpis } = useQuery<Kpi[], Error>({
    queryKey: ['kpisListForQuestionnaire', user?.id],
    queryFn: async () => {
      if (!user?.id) return [];
      const { data, error } = await supabase
        .from('kpis')
        .select('*, pillars(id), pillar_blocks(id)') // Select pillar_id and pillar_block_id for filtering
        .eq('user_id', user.id)
        .order('question', { ascending: true });
      if (error) throw error;
      return data;
    },
    enabled: !!user?.id,
  });

  const { data: scoringScales, isLoading: isLoadingScoringScales } = useQuery<ScoringScale[], Error>({
    queryKey: ['scoringScalesListForQuestionnaire', user?.id],
    queryFn: async () => {
      if (!user?.id) return [];
      const { data, error } = await supabase
        .from('scoring_scales')
        .select('*')
        .eq('user_id', user.id)
        .order('score', { ascending: true });
      if (error) throw error;
      return data;
    },
    enabled: !!user?.id,
  });

  const filteredKpisForEdit = useMemo(() => {
    if (!kpis || !selectedDiagnosticIdForEdit || !diagnostics) return [];
    const selectedDiagnostic = diagnostics.find(d => d.id === selectedDiagnosticIdForEdit);
    if (!selectedDiagnostic || !selectedDiagnostic.pillar_id || !selectedDiagnostic.pillar_block_id) return [];

    return kpis.filter(kpi =>
      kpi.pillars?.id === selectedDiagnostic.pillar_id &&
      kpi.pillar_blocks?.id === selectedDiagnostic.pillar_block_id
    );
  }, [kpis, selectedDiagnosticIdForEdit, diagnostics]);

  const mutationOptions = {
    onSuccess: () => {
      queryClient.invalidateQueries({ queryKey: ['diagnosticQuestionnaires', user?.id, selectedCompany?.id, selectedDiagnosticToAnswer] }); // Invalidate specific query
      setIsEditDialogOpen(false); // Fechar o diálogo de edição
      setEditingQuestionnaire(null);
    },
    onError: (error: Error) => {
      showError(`Erro: ${error.message}`);
    },
  };

  const updateQuestionnaireMutation = useMutation({
    mutationFn: async (data: DiagnosticQuestionnaireFormData) => {
      if (!editingQuestionnaire?.id) throw new Error("ID da resposta do questionário está faltando.");
      if (!user?.id || !selectedCompany?.id) throw new Error("Usuário não autenticado ou empresa não selecionada.");
      const { error } = await supabase
        .from('diagnostic_questionnaires')
        .update({
          diagnostic_id: data.diagnostic_id,
          kpi_id: data.kpi_id,
          score_id: data.score_id,
          evidence: data.evidence || null,
          order_number: data.order_number, // Adicionado
        })
        .eq('id', editingQuestionnaire.id)
        .eq('user_id', user.id)
        .eq('company_id', selectedCompany.id);
      if (error) throw error;
    },
    ...mutationOptions,
    onSuccess: () => {
      mutationOptions.onSuccess();
      showSuccess('Resposta do questionário atualizada com sucesso!');
    },
  });

  const deleteQuestionnaireMutation = useMutation({
    mutationFn: async (id: string) => {
      if (!user?.id || !selectedCompany?.id) throw new Error("Usuário não autenticado ou empresa não selecionada.");
      const { error, count } = await supabase
        .from('diagnostic_questionnaires')
        .delete()
        .eq('id', id)
        .eq('user_id', user.id)
        .eq('company_id', selectedCompany.id);
      
      if (error) {
        throw error;
      }
      if (count === 0) {
        throw new Error("Resposta do questionário não encontrada ou você não tem permissão para excluí-la.");
      }
    },
    ...mutationOptions,
    onSuccess: () => {
      mutationOptions.onSuccess();
      showSuccess('Resposta do questionário excluída com sucesso!');
    },
  });

  const onEditSubmit = (data: DiagnosticQuestionnaireFormData) => {
    updateQuestionnaireMutation.mutate(data);
  };

  const handleAddQuestionsClick = () => {
    if (!selectedCompany) {
      showError("Por favor, selecione uma empresa na barra lateral para adicionar perguntas.");
      return;
    }
    if (!selectedPillarFilter || selectedPillarFilter === 'all') {
      showError("Por favor, selecione um pilar para adicionar perguntas.");
      return;
    }
    if (!diagnostics || diagnostics.length === 0) {
      showError("Nenhum diagnóstico encontrado para o pilar selecionado. Crie um em 'OPS | Diagnósticos' primeiro.");
      return;
    }
    if (!selectedDiagnosticToAnswer) {
      showError("Por favor, selecione um diagnóstico para adicionar perguntas.");
      return;
    }
    setIsAddQuestionsDialogOpen(true);
  };

  const handleEditClick = (questionnaire: DiagnosticQuestionnaire) => {
    setEditingQuestionnaire(questionnaire);
    setIsEditDialogOpen(true);
  };

  const handleDeleteClick = (id: string) => {
    if (window.confirm('Tem certeza que deseja excluir esta resposta do questionário?')) {
      deleteQuestionnaireMutation.mutate(id);
    }
  };

  const isMutating = updateQuestionnaireMutation.isPending || deleteQuestionnaireMutation.isPending;
  const isLoadingPage = isLoadingAllCompanyDiagnostics || isLoadingAvailablePillarsForFilter || isLoadingAllDiagnosticStatuses || isLoadingDiagnostics || isLoadingKpis || isLoadingScoringScales || isLoadingQuestionnaires;

  if (!selectedCompany) {
    return (
      <div className="text-center text-muted-foreground py-8">
        Por favor, selecione uma empresa na barra lateral para gerenciar o questionário de diagnóstico.
      </div>
    );
  }

  if (isLoadingPage) {
    return (
      <div className="text-center text-muted-foreground">Carregando questionários...</div>
    );
  }

  if (errorQuestionnaires) {
    return <div className="text-center text-destructive">Erro ao carregar questionários: {errorQuestionnaires.message}</div>;
  }

  return (
    <div className="space-y-6">
      <Card className="bg-card backdrop-blur-md border border-border shadow-lg rounded-2xl">
        <CardHeader className="flex flex-row items-center justify-between">
          <div>
            <CardTitle className="text-foreground uppercase font-bold">Gerenciar Questionário do Diagnóstico</CardTitle>
            <CardDescription className="text-muted-foreground">
              Respostas do questionário para a empresa: <span className="font-semibold">{selectedCompany.name}</span>
            </CardDescription>
          </div>
          <Button onClick={handleAddQuestionsClick} className="bg-sollux-red hover:bg-sollux-red/90 text-white rounded-lg" disabled={!selectedDiagnosticToAnswer}>
            <Plus className="mr-2 h-4 w-4" /> Adicionar Perguntas
          </Button>
        </CardHeader>
        <CardContent>
          {/* Seletor de Pilar para Filtro */}
          <div className="mb-4">
            <Label className="text-foreground">Filtrar por Pilar</Label>
            <Select
              onValueChange={(value) => {
                setSelectedPillarFilter(value);
              }}
              value={selectedPillarFilter}
              disabled={isLoadingAvailablePillarsForFilter}
            >
              <SelectTrigger className="rounded-lg">
                <SelectValue placeholder="Todos os Pilares" />
              </SelectTrigger>
              <SelectContent>
                <SelectItem value="all">Todos os Pilares</SelectItem>
                {isLoadingAvailablePillarsForFilter ? (
                  <SelectItem value="loading" disabled>Carregando pilares...</SelectItem>
                ) : (availablePillarsForFilter?.length || 0) === 0 ? (
                  <SelectItem value="no-pillars" disabled>Nenhum pilar com diagnóstico cadastrado.</SelectItem>
                ) : (
                  availablePillarsForFilter?.map((pillar) => (
                    pillar.id && pillar.id !== '' ? (
                      <SelectItem key={pillar.id} value={pillar.id}>
                        {pillar.description}
                      </SelectItem>
                    ) : null
                  ))
                )}
              </SelectContent>
            </Select>
          </div>

          {/* Seletor de Status do Diagnóstico para Filtro */}
          <div className="mb-6">
            <Label className="text-foreground">Filtrar por Status do Diagnóstico</Label>
            <Select
              onValueChange={(value) => {
                setSelectedDiagnosticStatusFilter(value);
              }}
              value={selectedDiagnosticStatusFilter}
              disabled={isLoadingAllDiagnosticStatuses}
            >
              <SelectTrigger className="rounded-lg">
                <SelectValue placeholder="Todos os Status" />
              </SelectTrigger>
              <SelectContent>
                <SelectItem value="all">Todos os Status</SelectItem>
                {isLoadingAllDiagnosticStatuses ? (
                  <SelectItem value="loading" disabled>Carregando status...</SelectItem>
                ) : (allDiagnosticStatuses?.length || 0) === 0 ? (
                  <SelectItem value="no-statuses" disabled>Nenhum status cadastrado.</SelectItem>
                ) : (
                  allDiagnosticStatuses?.map((status) => (
                    status.id && status.id !== '' ? (
                      <SelectItem key={status.id} value={status.id}>
                        {status.description}
                      </SelectItem>
                    ) : null
                  ))
                )}
              </SelectContent>
            </Select>
          </div>

          {/* Seletor de Diagnóstico */}
          <div className="mb-6">
            <Label className="text-foreground">Selecionar Diagnóstico</Label>
            <Select
              onValueChange={setSelectedDiagnosticToAnswer}
              value={selectedDiagnosticToAnswer || 'placeholder'}
              disabled={isLoadingDiagnostics || (diagnostics?.length || 0) === 0}
            >
              <SelectTrigger className="rounded-lg">
                <SelectValue placeholder="Selecione um diagnóstico" />
              </SelectTrigger>
              <SelectContent>
                <SelectItem value="placeholder" disabled>Selecione um Diagnóstico</SelectItem>
                {isLoadingDiagnostics ? (
                  <SelectItem value="loading" disabled>Carregando diagnósticos...</SelectItem>
                ) : (diagnostics?.length || 0) === 0 ? (
                  <SelectItem value="no-diagnostics" disabled>Nenhum diagnóstico encontrado para os filtros aplicados.</SelectItem>
                ) : (
                  diagnostics?.map((diagnostic) => (
                    diagnostic.id && diagnostic.id !== '' ? (
                      <SelectItem key={diagnostic.id} value={diagnostic.id}>
                        {diagnostic.id.substring(0, 8)}... ({diagnostic.pillars?.description || 'N/A'} / {diagnostic.pillar_blocks?.name || 'N/A'})
                      </SelectItem>
                    ) : null
                  ))
                )}
              </SelectContent>
            </Select>
            {!selectedDiagnosticToAnswer && (diagnostics?.length || 0) > 0 && (
              <p className="text-sm font-medium text-destructive mt-2">Por favor, selecione um diagnóstico para adicionar perguntas.</p>
            )}
            {(diagnostics?.length || 0) === 0 && (selectedPillarFilter !== 'all' || selectedDiagnosticStatusFilter !== 'all') && (
              <p className="text-sm text-destructive mt-2">
                Nenhum diagnóstico encontrado com os filtros aplicados. Tente ajustar os filtros ou criar novos diagnósticos.
              </p>
            )}
          </div>

          {/* Tabela de Questionários (só aparece se um diagnóstico for selecionado) */}
          {selectedDiagnosticToAnswer ? (
            <Table>
              <TableHeader>
                <TableRow>
                  <TableHead className="text-foreground w-[80px]">Ordem</TableHead>
                  <TableHead className="text-foreground">Diagnóstico</TableHead>
                  <TableHead className="text-foreground">Pergunta (KPI)</TableHead>
                  <TableHead className="text-right text-foreground">Ações</TableHead>
                </TableRow>
              </TableHeader>
              <TableBody>
                {questionnaires?.length === 0 ? (
                  <TableRow>
                    <TableCell colSpan={4} className="text-center text-muted-foreground">
                      Nenhuma resposta de questionário encontrada para este diagnóstico.
                    </TableCell>
                  </TableRow>
                ) : (
                  questionnaires?.map((q) => (
                    <TableRow key={q.id}>
                      <TableCell className="font-bold text-sollux-red">{q.order_number || 'N/A'}</TableCell>
                      <TableCell className="font-medium text-foreground">
                        {q.diagnostics?.id.substring(0, 8)}... ({q.diagnostics?.pillars?.description || 'N/A'} / {q.diagnostics?.pillar_blocks?.name || 'N/A'})
                      </TableCell>
                      <TableCell className="text-muted-foreground">
                        {q.kpis?.question || 'N/A'}
                      </TableCell>
                      <TableCell className="text-right">
                        <Button
                          variant="ghost"
                          size="sm"
                          onClick={() => handleEditClick(q)}
                          className="mr-2 text-foreground hover:bg-accent rounded-lg"
                          disabled={isMutating}
                        >
                          <Edit className="h-4 w-4" />
                        </Button>
                        <Button
                          variant="destructive"
                          size="sm"
                          onClick={() => handleDeleteClick(q.id)}
                          className="bg-sollux-red hover:bg-red-700 text-white rounded-lg"
                          disabled={isMutating}
                        >
                          <Trash2 className="h-4 w-4" />
                        </Button>
                      </TableCell>
                    </TableRow>
                  ))
                )}
              </TableBody>
            </Table>
          ) : (
            <div className="text-center text-muted-foreground py-8">
              Selecione um diagnóstico acima para visualizar e gerenciar suas perguntas.
            </div>
          )}
        </CardContent>
      </Card>

      {/* Novo Diálogo para Adicionar Múltiplas Perguntas */}
      <AddMultipleDiagnosticQuestionsDialog
        open={isAddQuestionsDialogOpen}
        onOpenChange={setIsAddQuestionsDialogOpen}
        diagnosticId={selectedDiagnosticToAnswer}
      />

      {/* Diálogo para Editar UMA Pergunta (o antigo diálogo de adição, agora para edição) */}
      <Dialog open={isEditDialogOpen} onOpenChange={setIsEditDialogOpen}>
        <DialogContent className="sm:max-w-[425px] bg-card backdrop-blur-md rounded-2xl shadow-lg border border-border">
          <DialogHeader>
            <DialogTitle className="text-foreground">Editar Resposta do Questionário</DialogTitle>
            <DialogDescription className="text-muted-foreground">
              Atualize os detalhes da resposta.
            </DialogDescription>
          </DialogHeader>
          <Form {...editForm}>
            <form onSubmit={editForm.handleSubmit(onEditSubmit)} className="space-y-4">
              <FormField
                control={editForm.control}
                name="diagnostic_id"
                render={({ field }) => (
                  <FormItem>
                    <FormLabel className="text-foreground">Diagnóstico</FormLabel>
                    <Select onValueChange={field.onChange} value={field.value} disabled={isLoadingDiagnostics}>
                      <FormControl>
                        <SelectTrigger className="rounded-lg">
                          <SelectValue placeholder="Selecione um diagnóstico" />
                        </SelectTrigger>
                      </FormControl>
                      <SelectContent>
                        {diagnostics?.length === 0 ? (
                          <SelectItem value="no-diagnostics" disabled>Nenhum diagnóstico cadastrado</SelectItem>
                        ) : (
                          diagnostics?.map((diagnostic) => (
                            diagnostic.id && diagnostic.id !== '' ? (
                              <SelectItem key={diagnostic.id} value={diagnostic.id}>
                                {diagnostic.id.substring(0, 8)}... ({diagnostic.pillars?.description || 'N/A'} / {diagnostic.pillar_blocks?.name || 'N/A'})
                              </SelectItem>
                            ) : null
                          ))
                        )}
                      </SelectContent>
                    </Select>
                    <FormMessage />
                  </FormItem>
                )}
              />
              <FormField
                control={editForm.control}
                name="kpi_id"
                render={({ field }) => (
                  <FormItem>
                    <FormLabel className="text-foreground">Pergunta (KPI)</FormLabel>
                    <Select onValueChange={field.onChange} value={field.value} disabled={!selectedDiagnosticIdForEdit || isLoadingKpis || filteredKpisForEdit.length === 0}>
                      <FormControl>
                        <SelectTrigger className="rounded-lg">
                          <SelectValue placeholder="Selecione uma pergunta" />
                        </SelectTrigger>
                      </FormControl>
                      <SelectContent>
                        {filteredKpisForEdit.length === 0 ? (
                          <SelectItem value="no-kpis" disabled>Nenhuma pergunta para este diagnóstico</SelectItem>
                        ) : (
                          filteredKpisForEdit.map((kpi) => (
                            kpi.id && kpi.id !== '' ? (
                              <SelectItem key={kpi.id} value={kpi.id}>
                                {kpi.question}
                              </SelectItem>
                            ) : null
                          ))
                        )}
                      </SelectContent>
                    </Select>
                    <FormMessage />
                  </FormItem>
                )}
              />
              <FormField
                control={editForm.control}
                name="order_number"
                render={({ field }) => (
                  <FormItem>
                    <FormLabel className="text-foreground">Ordem da Pergunta</FormLabel>
                    <FormControl>
                      <Input
                        type="number"
                        placeholder="Ex: 1"
                        {...field}
                        onChange={(e) => field.onChange(e.target.value ? Number(e.target.value) : undefined)} // Garante a conversão para número
                        min={1} // Mínimo 1
                        max={999999} // Máximo 6 dígitos
                        className="rounded-lg"
                      />
                    </FormControl>
                    <FormMessage />
                  </FormItem>
                )}
              />
              <FormField
                control={editForm.control}
                name="score_id"
                render={({ field }) => (
                  <FormItem>
                    <FormLabel className="text-foreground">Nota</FormLabel>
                    <Select onValueChange={field.onChange} value={field.value} disabled={isLoadingScoringScales}>
                      <FormControl>
                        <SelectTrigger className="rounded-lg">
                          <SelectValue placeholder="Selecione uma nota" />
                        </SelectTrigger>
                      </FormControl>
                      <SelectContent>
                        {scoringScales?.length === 0 ? (
                          <SelectItem value="no-scores" disabled>Nenhuma régua de pontuação cadastrada</SelectItem>
                        ) : (
                          scoringScales?.map((score) => (
                            score.id && score.id !== '' ? (
                              <SelectItem key={score.id} value={score.id}>
                                {score.score} - {score.description}
                              </SelectItem>
                            ) : null
                          ))
                        )}
                      </SelectContent>
                    </Select>
                    <FormMessage />
                  </FormItem>
                )}
              />
              <FormField
                control={editForm.control}
                name="evidence"
                render={({ field }) => (
                  <FormItem>
                    <FormLabel className="text-foreground">Evidência (Opcional)</FormLabel>
                    <FormControl>
                      <Textarea placeholder="Descreva as evidências para esta resposta." {...field} className="rounded-lg" rows={4} />
                    </FormControl>
                    <FormMessage />
                  </FormItem>
                )}
              />
              <DialogFooter className="flex justify-end gap-2 pt-4">
                <Button type="button" variant="outline" onClick={() => setIsEditDialogOpen(false)} disabled={isMutating} className="rounded-lg">
                  Cancelar
                </Button>
                <Button type="submit" disabled={isMutating} className="rounded-lg bg-sollux-red hover:bg-sollux-orange">
                  Salvar Alterações
                </Button>
              </DialogFooter>
            </form>
          </Form>
        </DialogContent>
      </Dialog>
    </div>
  );
};

export default DiagnosticQuestionnairePage;

import React, { useState, useEffect, useMemo } from 'react';
import { useForm } from 'react-hook-form';
import { zodResolver } from '@hookform/resolvers/zod';
import * as z from 'zod';
import { Card, CardContent, CardHeader, CardTitle } from '@/components/ui/card';
import { Button } from '@/components/ui/button';
import { Input } from '@/components/ui/input';
import { Dialog, DialogContent, DialogHeader, DialogTitle, DialogFooter } from '@/components/ui/dialog';
import { Form, FormControl, FormField, FormItem, FormLabel, FormMessage } from '@/components/ui/form';
import { Table, TableBody, TableCell, TableHead, TableHeader, TableRow } from '@/components/ui/table';
import { Plus, Edit, Trash2, FileText, Eye } from 'lucide-react';
import { supabase } from '@/integrations/supabase/client';
import { showSuccess, showError } from '@/utils/toast';
import { Document, DocumentFormData } from '@/types/document';
import { useQuery, useMutation, useQueryClient } from '@tanstack/react-query';
import { useSession } from '@/components/SessionContextProvider';
import { Textarea } from '@/components/ui/textarea';
import { Select, SelectContent, SelectItem, SelectTrigger, SelectValue } from '@/components/ui/select';
import DatePicker from '@/components/DatePicker';
import { format } from 'date-fns';
import { ptBR } from 'date-fns/locale';
import ReactQuill from 'react-quill';
import 'react-quill/dist/quill.snow.css';
import { BasicProfileInfo } from '@/types/profile'; // Importar BasicProfileInfo
import { Switch } from '@/components/ui/switch';
import SearchableUserSelect from '@/components/SearchableUserSelect'; // Importar o novo componente
import { Badge } from '@/components/ui/badge';

const formSchema = z.object({
  title: z.string().min(1, { message: 'O título é obrigatório.' }),
  version: z.string().min(1, { message: 'A versão é obrigatória.' }),
  content: z.string().min(1, { message: 'O conteúdo é obrigatório.' }),
  publication_date: z.date({ required_error: 'A data de publicação é obrigatória.' }),
  target_user_id: z.string().optional().nullable(), // 'all' or specific user ID
  status: z.boolean().default(true), // Novo campo de status
});

const DocumentManagementPage: React.FC = () => {
  const queryClient = useQueryClient();
  const { user } = useSession();
  const [isDialogOpen, setIsDialogOpen] = useState(false);
  const [editingDocument, setEditingDocument] = useState<Document | null>(null);
  const [isViewContentDialogOpen, setIsViewContentDialogOpen] = useState(false);
  const [documentToViewContent, setDocumentToViewContent] = useState<Document | null>(null);

  const form = useForm<DocumentFormData>({
    resolver: zodResolver(formSchema),
    defaultValues: {
      title: '',
      version: '',
      content: '',
      publication_date: undefined,
      target_user_id: 'all',
      status: true, // Valor padrão para o novo campo
    },
  });

  const [editorLoaded, setEditorLoaded] = useState(false);
  useEffect(() => { setEditorLoaded(true); }, []);

  useEffect(() => {
    if (editingDocument) {
      const publicationDate = editingDocument.publication_date ? new Date(editingDocument.publication_date + 'T00:00:00') : undefined;
      form.reset({
        title: editingDocument.title,
        version: editingDocument.version,
        content: editingDocument.content,
        publication_date: publicationDate,
        target_user_id: editingDocument.target_user_id || 'all',
        status: editingDocument.status === 'active', // Mapear 'active'/'inactive' para boolean
      });
    } else {
      form.reset({
        title: '',
        version: '',
        content: '',
        publication_date: undefined,
        target_user_id: 'all',
        status: true,
      });
    }
  }, [editingDocument, form, isDialogOpen]);

  const { data: documents, isLoading: isLoadingDocuments, error: errorDocuments } = useQuery<Document[], Error>({
    queryKey: ['documents', user?.id],
    queryFn: async () => {
      if (!user?.id) return [];

      // 1. Fetch documents without direct profile join
      const { data: documentsData, error: documentsError } = await supabase
        .from('documents')
        .select('*') // Select all columns from documents
        .order('created_at', { ascending: false });

      if (documentsError) throw documentsError;
      if (!documentsData) return [];

      // 2. Collect all unique user IDs (creator and target) from the fetched documents
      const userIds = new Set<string>();
      documentsData.forEach(doc => {
        userIds.add(doc.creator_user_id);
        if (doc.target_user_id) {
          userIds.add(doc.target_user_id);
        }
      });

      const uniqueUserIds = Array.from(userIds);

      // 3. Fetch profiles for these user IDs
      let profilesMap = new Map<string, BasicProfileInfo>();
      if (uniqueUserIds.length > 0) {
        const { data: profilesData, error: profilesError } = await supabase
          .from('profiles')
          .select('id, first_name, last_name')
          .in('id', uniqueUserIds);

        if (profilesError) {
          console.error("Error fetching profiles for documents:", profilesError);
          // Log the error but proceed, as the main document data is still valid.
        } else if (profilesData) {
          profilesData.forEach(p => profilesMap.set(p.id, p));
        }
      }

      // 4. Map profiles back to documents
      const enrichedDocuments = documentsData.map(doc => ({
        ...doc,
        creator_profile: profilesMap.get(doc.creator_user_id) || null,
        target_profile: doc.target_user_id ? (profilesMap.get(doc.target_user_id) || null) : null,
      }));

      return enrichedDocuments;
    },
    enabled: !!user?.id,
  });

  const { data: allUsers, isLoading: isLoadingUsers } = useQuery<BasicProfileInfo[], Error>({
    queryKey: ['allUsersForDocuments'],
    queryFn: async () => {
      const { data, error } = await supabase.from('profiles').select('id, first_name, last_name');
      if (error) throw error;
      return data;
    },
    enabled: !!user?.id,
  });

  const userOptions = useMemo(() => {
    const options = allUsers?.map(u => ({
      value: u.id,
      label: `${u.first_name || ''} ${u.last_name || ''}`.trim() || `Usuário ${u.id.substring(0, 8)}`
    })) || [];
    return [{ value: 'all', label: 'Todos os Usuários' }, ...options];
  }, [allUsers]);

  const mutationOptions = {
    onSuccess: () => {
      queryClient.invalidateQueries({ queryKey: ['documents', user?.id] });
      setIsDialogOpen(false);
      setEditingDocument(null);
    },
    onError: (error: Error) => {
      showError(`Erro: ${error.message}`);
    },
  };

  const createDocumentMutation = useMutation({
    mutationFn: async (data: DocumentFormData) => {
      if (!user?.id) throw new Error("Usuário não autenticado.");
      const { data: newDocument, error } = await supabase
        .from('documents')
        .insert({
          title: data.title,
          version: data.version,
          content: data.content,
          publication_date: data.publication_date ? format(data.publication_date, 'yyyy-MM-dd') : null,
          target_user_id: data.target_user_id === 'all' ? null : data.target_user_id,
          creator_user_id: user.id,
          status: data.status ? 'active' : 'inactive', // Salvar status
        })
        .select()
        .single();
      if (error) throw error;
      return newDocument;
    },
    ...mutationOptions,
    onSuccess: () => {
      mutationOptions.onSuccess();
      showSuccess('Documento criado com sucesso!');
    },
  });

  const updateDocumentMutation = useMutation({
    mutationFn: async (data: DocumentFormData) => {
      if (!editingDocument?.id) throw new Error("ID do documento está faltando.");
      if (!user?.id) throw new Error("Usuário não autenticado.");
      const { data: updatedDocument, error } = await supabase
        .from('documents')
        .update({
          title: data.title,
          version: data.version,
          content: data.content,
          publication_date: data.publication_date ? format(data.publication_date, 'yyyy-MM-dd') : null,
          target_user_id: data.target_user_id === 'all' ? null : data.target_user_id,
          status: data.status ? 'active' : 'inactive', // Atualizar status
        })
        .eq('id', editingDocument.id)
        .eq('creator_user_id', user.id)
        .select()
        .single();
      if (error) throw error;
      return updatedDocument;
    },
    ...mutationOptions,
    onSuccess: () => {
      mutationOptions.onSuccess();
      showSuccess('Documento atualizado com sucesso!');
    },
  });

  const deleteDocumentMutation = useMutation({
    mutationFn: async (id: string) => {
      if (!user?.id) throw new Error("Usuário não autenticado.");
      const { error, count } = await supabase
        .from('documents')
        .delete()
        .eq('id', id)
        .eq('creator_user_id', user.id);
      
      if (error) {
        throw error;
      }
      if (count === 0) {
        throw new Error("Documento não encontrado ou você não tem permissão para excluí-lo.");
      }
    },
    ...mutationOptions,
    onSuccess: () => {
      mutationOptions.onSuccess();
      showSuccess('Documento excluído com sucesso!');
    },
  });

  const onSubmit = (data: DocumentFormData) => {
    if (editingDocument) {
      updateDocumentMutation.mutate(data);
    } else {
      createDocumentMutation.mutate(data);
    }
  };

  const handleAddClick = () => {
    setEditingDocument(null);
    setIsDialogOpen(true);
  };

  const handleEditClick = (document: Document) => {
    setEditingDocument(document);
    setIsDialogOpen(true);
  };

  const handleViewContentClick = (document: Document) => {
    setDocumentToViewContent(document);
    setIsViewContentDialogOpen(true);
  };

  const handleDeleteClick = (id: string) => {
    if (window.confirm('Tem certeza que deseja excluir este documento?')) {
      deleteDocumentMutation.mutate(id);
    }
  };

  const isMutating = createDocumentMutation.isPending || updateDocumentMutation.isPending || deleteDocumentMutation.isPending;
  const isLoadingPage = isLoadingDocuments || isLoadingUsers;

  if (isLoadingPage) {
    return <div className="text-center text-muted-foreground">Carregando documentos...</div>;
  }

  if (errorDocuments) {
    return <div className="text-center text-destructive">Erro ao carregar documentos: {errorDocuments.message}</div>;
  }

  return (
    <div className="space-y-6">
      <Card className="bg-card backdrop-blur-md border border-border shadow-lg rounded-2xl">
        <CardHeader className="flex flex-row items-center justify-between">
          <CardTitle className="text-foreground uppercase font-bold">Gerenciar Documentos</CardTitle>
          <Button onClick={handleAddClick} className="bg-sollux-red hover:bg-sollux-red/90 text-white rounded-lg">
            <Plus className="mr-2 h-4 w-4" /> Adicionar Documento
          </Button>
        </CardHeader>
        <CardContent>
          <Table>
            <TableHeader>
              <TableRow>
                <TableHead className="text-foreground">Título</TableHead>
                <TableHead className="text-foreground">Versão</TableHead>
                <TableHead className="text-foreground">Publicado em</TableHead>
                <TableHead className="text-foreground">Para</TableHead>
                <TableHead className="text-foreground">Status</TableHead> {/* Nova coluna */}
                <TableHead className="text-right text-foreground">Ações</TableHead>
              </TableRow>
            </TableHeader>
            <TableBody>
              {documents?.length === 0 ? (
                <TableRow>
                  <TableCell colSpan={6} className="text-center text-muted-foreground">
                    Nenhum documento encontrado.
                  </TableCell>
                </TableRow>
              ) : (
                documents?.map((doc) => {
                  const targetUserName = doc.target_user_id
                    ? (doc.target_profile ? `${doc.target_profile.first_name || ''} ${doc.target_profile.last_name || ''}`.trim() : `Usuário ${doc.target_user_id.substring(0, 8)}`)
                    : 'Todos os Usuários';
                  return (
                    <TableRow key={doc.id}>
                      <TableCell className="font-medium text-foreground">{doc.title}</TableCell>
                      <TableCell className="text-muted-foreground">{doc.version}</TableCell>
                      <TableCell className="text-muted-foreground">
                        {format(new Date(doc.publication_date + 'T00:00:00'), 'dd/MM/yyyy', { locale: ptBR })}
                      </TableCell>
                      <TableCell className="text-muted-foreground">
                        {doc.target_user_id === user?.id ? 'Você' : targetUserName}
                      </TableCell>
                      <TableCell> {/* Nova célula para status */}
                        <Badge
                          variant={doc.status === 'active' ? 'default' : 'secondary'}
                          className={doc.status === 'active' ? 'bg-green-100 text-green-800 border-green-200' : 'bg-gray-100 text-gray-800 border-gray-200'}
                        >
                          {doc.status === 'active' ? 'Ativo' : 'Inativo'}
                        </Badge>
                      </TableCell>
                      <TableCell className="text-right flex justify-end items-center gap-1">
                        <Button
                          variant="ghost"
                          size="sm"
                          onClick={() => handleViewContentClick(doc)}
                          className="text-blue-600 hover:bg-blue-50 rounded-lg"
                          disabled={isMutating}
                          title="Visualizar Conteúdo"
                        >
                          <Eye className="h-4 w-4" />
                        </Button>
                        <Button
                          variant="ghost"
                          size="sm"
                          onClick={() => handleEditClick(doc)}
                          className="mr-2 text-foreground hover:bg-accent rounded-lg"
                          disabled={isMutating}
                          title="Editar Documento"
                        >
                          <Edit className="h-4 w-4" />
                        </Button>
                        <Button
                          variant="destructive"
                          size="sm"
                          onClick={() => handleDeleteClick(doc.id)}
                          className="bg-sollux-red hover:bg-red-700 text-white rounded-lg"
                          disabled={isMutating}
                          title="Excluir Documento"
                        >
                          <Trash2 className="h-4 w-4" />
                        </Button>
                      </TableCell>
                    </TableRow>
                  );
                })
              )}
            </TableBody>
          </Table>
        </CardContent>
      </Card>

      <Dialog open={isDialogOpen} onOpenChange={setIsDialogOpen}>
        <DialogContent className="sm:max-w-2xl bg-card backdrop-blur-md rounded-2xl shadow-lg border border-border max-h-[90vh] overflow-y-auto">
          <DialogHeader>
            <DialogTitle className="text-foreground">{editingDocument ? 'Editar Documento' : 'Adicionar Novo Documento'}</DialogTitle>
          </DialogHeader>
          <Form {...form}>
            <form onSubmit={form.handleSubmit(onSubmit)} className="space-y-4">
              <FormField
                control={form.control}
                name="title"
                render={({ field }) => (
                  <FormItem>
                    <FormLabel className="text-foreground">Título</FormLabel>
                    <FormControl>
                      <Input placeholder="Título do documento" {...field} className="rounded-lg text-foreground placeholder:text-muted-foreground" />
                    </FormControl>
                    <FormMessage />
                  </FormItem>
                )}
              />
              <FormField
                control={form.control}
                name="version"
                render={({ field }) => (
                  <FormItem>
                    <FormLabel className="text-foreground">Versão do Documento</FormLabel>
                    <FormControl>
                      <Input placeholder="Ex: 1.0.0" {...field} className="rounded-lg text-foreground placeholder:text-muted-foreground" />
                    </FormControl>
                    <FormMessage />
                  </FormItem>
                )}
              />
              <FormField
                control={form.control}
                name="publication_date"
                render={({ field }) => (
                  <FormItem className="flex flex-col">
                    <FormLabel className="text-foreground text-left">Data de Publicação</FormLabel>
                    <FormControl>
                      <DatePicker
                        date={field.value}
                        setDate={field.onChange}
                        placeholder="Selecione a data de publicação"
                        disabled={isMutating}
                      />
                    </FormControl>
                    <FormMessage />
                  </FormItem>
                )}
              />
              <FormField
                control={form.control}
                name="target_user_id"
                render={({ field }) => (
                  <FormItem>
                    <FormLabel className="text-foreground">Visibilidade</FormLabel>
                    <FormControl>
                      <SearchableUserSelect
                        options={userOptions}
                        value={field.value || 'all'}
                        onChange={field.onChange}
                        placeholder="Selecione o público-alvo"
                        disabled={isLoadingUsers || isMutating}
                      />
                    </FormControl>
                    <FormMessage />
                  </FormItem>
                )}
              />
              <FormField
                control={form.control}
                name="status"
                render={({ field }) => (
                  <FormItem className="flex flex-row items-center justify-between rounded-lg border p-3 shadow-sm">
                    <div className="space-y-0.5">
                      <FormLabel className="text-foreground">Status</FormLabel>
                    </div>
                    <FormControl>
                      <Switch
                        checked={field.value}
                        onCheckedChange={field.onChange}
                        disabled={isMutating}
                      />
                    </FormControl>
                  </FormItem>
                )}
              />
              <FormField
                control={form.control}
                name="content"
                render={({ field }) => (
                  <FormItem>
                    <FormLabel className="text-foreground">Conteúdo</FormLabel>
                    <FormControl>
                      {editorLoaded ? (
                        <ReactQuill
                          theme="snow"
                          value={field.value}
                          onChange={field.onChange}
                          className="bg-card rounded-lg"
                          modules={{
                            toolbar: [
                              [{ 'header': [1, 2, false] }],
                              ['bold', 'italic', 'underline', 'strike', 'link'],
                              [{ 'list': 'ordered'}, { 'list': 'bullet' }],
                              [{ 'indent': '-1'}, { 'indent': '+1' }],
                              ['image', 'code-block'],
                              [{ 'color': [] }, { 'background': [] }],
                              ['clean']
                            ],
                          }}
                        />
                      ) : (
                        <div className="h-[200px] w-full bg-muted rounded-lg flex items-center justify-center text-muted-foreground">
                          Carregando editor de texto...
                        </div>
                      )}
                    </FormControl>
                    <FormMessage />
                  </FormItem>
                )}
              />
              <DialogFooter className="flex justify-end gap-2 pt-4">
                <Button type="button" variant="outline" onClick={() => setIsDialogOpen(false)} disabled={isMutating} className="rounded-lg text-foreground hover:bg-accent">
                  Cancelar
                </Button>
                <Button type="submit" disabled={isMutating} className="rounded-lg bg-sollux-red hover:bg-sollux-orange">
                  {editingDocument ? 'Salvar Alterações' : 'Adicionar Documento'}
                </Button>
              </DialogFooter>
            </form>
          </Form>
        </DialogContent>
      </Dialog>

      {/* Dialog para Visualizar Conteúdo do Documento */}
      <Dialog open={isViewContentDialogOpen} onOpenChange={setIsViewContentDialogOpen}>
        <DialogContent className="sm:max-w-3xl bg-card backdrop-blur-md rounded-2xl shadow-lg border border-border max-h-[90vh] overflow-y-auto">
          <DialogHeader>
            <DialogTitle className="text-foreground">Visualizar Documento: {documentToViewContent?.title}</DialogTitle>
          </DialogHeader>
          {documentToViewContent && (
            <div className="space-y-4 py-4">
              <div className="grid grid-cols-2 gap-4 text-sm bg-muted p-3 rounded-lg">
                <div>
                  <p className="font-medium text-muted-foreground">Versão:</p>
                  <p className="text-foreground">{documentToViewContent.version}</p>
                </div>
                <div>
                  <p className="font-medium text-muted-foreground">Publicado em:</p>
                  <p className="text-foreground">
                    {format(new Date(documentToViewContent.publication_date + 'T00:00:00'), 'dd/MM/yyyy', { locale: ptBR })}
                  </p>
                </div>
                <div>
                  <p className="font-medium text-muted-foreground">Status:</p>
                  <Badge
                    variant={documentToViewContent.status === 'active' ? 'default' : 'secondary'}
                    className={documentToViewContent.status === 'active' ? 'bg-green-100 text-green-800 border-green-200' : 'bg-gray-100 text-gray-800 border-gray-200'}
                  >
                    {documentToViewContent.status === 'active' ? 'Ativo' : 'Inativo'}
                  </Badge>
                </div>
              </div>
              <div className="prose max-w-none text-foreground" dangerouslySetInnerHTML={{ __html: documentToViewContent.content }} />
            </div>
          )}
          <DialogFooter>
            <Button variant="outline" onClick={() => setIsViewContentDialogOpen(false)} className="rounded-lg text-foreground hover:bg-accent">
              Fechar
            </Button>
          </DialogFooter>
        </DialogContent>
      </Dialog>
    </div>
  );
};

export default DocumentManagementPage;

import React, { useMemo, useState, useEffect } from 'react';
import { Card, CardContent, CardHeader, CardTitle, CardDescription } from '@/components/ui/card';
import { Loader2, Award, CheckCircle, Clock, XCircle, TrendingUp, LayoutDashboard, Settings } from 'lucide-react';
import { supabase } from '@/integrations/supabase/client';
import { showSuccess, showError } from '@/utils/toast';
import { useQuery } from '@tanstack/react-query';
import { useSession } from '@/components/SessionContextProvider';
import { useCompany } from '@/components/CompanyContext';
import { Diagnostic } from '@/types/diagnostic';
import { DiagnosticQuestionnaire } from '@/types/diagnosticQuestionnaire';
import { Pillar } from '@/types/pillar';
import { PillarBlock } from '@/types/pillarBlock';
import { ClassificationScale } from '@/types/classificationScale';
import { DiagnosticStatus } from '@/types/diagnosticStatus';
import { Badge } from '@/components/ui/badge';
import { PieChart, Pie, Cell, ResponsiveContainer, Tooltip as RechartsTooltip, Legend } from 'recharts';
