import { ContractType } from '@/types/contractType';
import { WorkModel } from '@/types/workModel';

const emptyStringToUndefined = z.preprocess(
  (val) => (val === "" ? undefined : val),
  z.any()
);

const formSchema = z.object({
  title: z.string().min(1, { message: 'O título da vaga é obrigatório.' }),
  job_sector_id: z.string().min(1, { message: 'A área/setor é obrigatória.' }),
  contract_type_id: z.string().min(1, { message: 'O tipo de contrato é obrigatório.' }),
  work_model_id: z.string().min(1, { message: 'O modelo de trabalho é obrigatório.' }),
  city: z.string().optional(),
  state: z.string().optional(),
  publication_deadline_days: emptyStringToUndefined.pipe(z.coerce.number().int().positive().optional()),
  status: z.boolean().default(true),
  short_summary: z.string().optional(),
  detailed_description: z.string().min(1, { message: 'A descrição detalhada é obrigatória.' }),
  mandatory_requirements: z.string().optional(),
  differential_requirements: z.string().optional(),
  benefits: z.string().optional(),
  salary_min: emptyStringToUndefined.pipe(z.coerce.number().positive().optional()),
  salary_max: emptyStringToUndefined.pipe(z.coerce.number().positive().optional()),
  hashtags: z.string().optional(),
}).refine(data => {
  if (data.salary_min !== undefined && data.salary_max !== undefined) {
    return data.salary_max >= data.salary_min;
  }
  return true;
}, {
  message: "O salário máximo deve ser maior ou igual ao mínimo.",
  path: ["salary_max"],
});

const JobFormPage: React.FC = () => {
  const queryClient = useQueryClient();
  const { user } = useSession();
  const { selectedCompany } = useCompany();
  const navigate = useNavigate();
  const { id: jobId } = useParams<{ id: string }>();
  const isEditing = !!jobId;

  const { data: jobSectors, isLoading: isLoadingSectors } = useQuery<JobSector[]>({ queryKey: ['jobSectors'], queryFn: async () => { const { data, error } = await supabase.from('job_sectors').select('*'); if (error) throw error; return data; } });
  const { data: contractTypes, isLoading: isLoadingContracts } = useQuery<ContractType[]>({ queryKey: ['contractTypes'], queryFn: async () => { const { data, error } = await supabase.from('contract_types').select('*'); if (error) throw error; return data; } });
  const { data: workModels, isLoading: isLoadingModels } = useQuery<WorkModel[]>({ queryKey: ['workModels'], queryFn: async () => { const { data, error } = await supabase.from('work_models').select('*'); if (error) throw error; return data; } });

  const { data: editingJob, isLoading: isLoadingJob } = useQuery<Job, Error>({
    queryKey: ['job', jobId],
    queryFn: async () => {
      const { data, error } = await supabase.from('jobs').select('*').eq('id', jobId).single();
      if (error) throw error;
      return data;
    },
    enabled: isEditing,
  });

  const form = useForm<z.infer<typeof formSchema>>({
    resolver: zodResolver(formSchema),
    defaultValues: {
      status: true,
      title: '',
      job_sector_id: '',
      contract_type_id: '',
      work_model_id: '',
      city: '',
      state: '',
      publication_deadline_days: undefined,
      short_summary: '',
      detailed_description: '',
      mandatory_requirements: '',
      differential_requirements: '',
      benefits: '',
      salary_min: undefined,
      salary_max: undefined,
      hashtags: '',
    },
  });

  useEffect(() => {
    if (isEditing && editingJob) {
      form.reset({
        title: editingJob.title,
        job_sector_id: editingJob.job_sector_id || '',
        contract_type_id: editingJob.contract_type_id || '',
        work_model_id: editingJob.work_model_id || '',
        city: editingJob.city || '',
        state: editingJob.state || '',
        publication_deadline_days: editingJob.publication_deadline_days || undefined,
        status: editingJob.status === 'active',
        short_summary: editingJob.short_summary || '',
        detailed_description: editingJob.detailed_description || '',
        mandatory_requirements: editingJob.mandatory_requirements?.join('\n') || '',
        differential_requirements: editingJob.differential_requirements?.join('\n') || '',
        benefits: editingJob.benefits?.join('\n') || '',
        salary_min: editingJob.salary_min || undefined,
        salary_max: editingJob.salary_max || undefined,
        hashtags: editingJob.hashtags?.join(', ') || '',
      });
    }
  }, [isEditing, editingJob, form]);

  const mutation = useMutation({
    mutationFn: async (payload: any) => {
      if (isEditing) {
        const { error } = await supabase.from('jobs').update(payload).eq('id', jobId);
        if (error) throw error;
      } else {
        if (!user?.id || !selectedCompany?.id) throw new Error("Usuário ou empresa não selecionada.");
        const { error } = await supabase.from('jobs').insert({ ...payload, user_id: user.id, company_id: selectedCompany.id });
        if (error) throw error;
      }
    },
    onSuccess: () => {
      queryClient.invalidateQueries({ queryKey: ['jobs', selectedCompany?.id] });
      showSuccess(`Vaga ${isEditing ? 'atualizada' : 'criada'} com sucesso!`);
      navigate('/connect/jobs');
    },
    onError: (error: Error) => showError(`Erro: ${error.message}`),
  });

  const onSubmit = (data: z.infer<typeof formSchema>) => {
    const processMultiLine = (text?: string) => text?.split('\n').filter(line => line.trim() !== '') || null;
    const processHashtags = (text?: string) => text?.split(',').map(tag => tag.trim()).filter(tag => tag !== '') || null;

    const payload = {
      ...data,
      status: data.status ? 'active' : 'inactive',
      mandatory_requirements: processMultiLine(data.mandatory_requirements),
      differential_requirements: processMultiLine(data.differential_requirements),
      benefits: processMultiLine(data.benefits),
      hashtags: processHashtags(data.hashtags),
    };
    mutation.mutate(payload);
  };

  const isLoading = isLoadingSectors || isLoadingContracts || isLoadingModels || (isEditing && isLoadingJob) || mutation.isPending;

  return (
    <Form {...form}>
      <form onSubmit={form.handleSubmit(onSubmit)} className="space-y-6">
        <Card className="bg-card backdrop-blur-md border border-border shadow-lg rounded-2xl">
          <CardHeader><CardTitle className="text-foreground">Dados Básicos</CardTitle></CardHeader>
          <CardContent className="space-y-4">
            <div className="grid grid-cols-1 md:grid-cols-2 gap-4">
              <FormField control={form.control} name="title" render={({ field }) => <FormItem><FormLabel className="text-foreground">Título da vaga</FormLabel><FormControl><Input placeholder="Ex: Engenheiro de Software" {...field} /></FormControl><FormMessage /></FormItem>} />
              <FormField control={form.control} name="job_sector_id" render={({ field }) => <FormItem><FormLabel className="text-foreground">Área / Setor</FormLabel><Select onValueChange={field.onChange} value={field.value}><FormControl><SelectTrigger><SelectValue placeholder="Selecione..." /></SelectTrigger></FormControl><SelectContent>{jobSectors?.map(s => <SelectItem key={s.id} value={s.id}>{s.name}</SelectItem>)}</SelectContent></Select><FormMessage /></FormItem>} />
              <FormField control={form.control} name="contract_type_id" render={({ field }) => <FormItem><FormLabel className="text-foreground">Tipo de Contrato</FormLabel><Select onValueChange={field.onChange} value={field.value}><FormControl><SelectTrigger><SelectValue placeholder="Selecione..." /></SelectTrigger></FormControl><SelectContent>{contractTypes?.map(c => <SelectItem key={c.id} value={c.id}>{c.name}</SelectItem>)}</SelectContent></Select><FormMessage /></FormItem>} />
              <FormField control={form.control} name="work_model_id" render={({ field }) => <FormItem><FormLabel className="text-foreground">Modelo de Trabalho</FormLabel><Select onValueChange={field.onChange} value={field.value}><FormControl><SelectTrigger><SelectValue placeholder="Selecione..." /></SelectTrigger></FormControl><SelectContent>{workModels?.map(w => <SelectItem key={w.id} value={w.id}>{w.name}</SelectItem>)}</SelectContent></Select><FormMessage /></FormItem>} />
              <FormField control={form.control} name="city" render={({ field }) => <FormItem><FormLabel className="text-foreground">Localidade (Cidade)</FormLabel><FormControl><Input placeholder="Ex: São Paulo" {...field} /></FormControl><FormMessage /></FormItem>} />
              <FormField control={form.control} name="state" render={({ field }) => <FormItem><FormLabel className="text-foreground">Estado</FormLabel><FormControl><Input placeholder="Ex: SP" {...field} /></FormControl><FormMessage /></FormItem>} />
              <FormField control={form.control} name="publication_deadline_days" render={({ field }) => <FormItem><FormLabel className="text-foreground">Prazo de publicação (dias)</FormLabel><FormControl><Input type="number" placeholder="Ex: 30" {...field} /></FormControl><FormMessage /></FormItem>} />
              <FormField control={form.control} name="status" render={({ field }) => <FormItem className="flex flex-col"><FormLabel className="text-foreground">Status da Vaga</FormLabel><div className="flex items-center gap-2 pt-2"><FormControl><Switch checked={field.value} onCheckedChange={field.onChange} /></FormControl><FormLabel className="text-muted-foreground">{field.value ? 'Ativa' : 'Inativa'}</FormLabel></div><FormMessage /></FormItem>} />
            </div>
          </CardContent>
        </Card>

        <Card className="bg-card backdrop-blur-md border border-border shadow-lg rounded-2xl">
          <CardHeader><CardTitle className="text-foreground">Descrição da Vaga</CardTitle></CardHeader>
          <CardContent className="space-y-4">
            <FormField control={form.control} name="short_summary" render={({ field }) => <FormItem><FormLabel className="text-foreground">Resumo Curto da Vaga</FormLabel><FormControl><Textarea placeholder="Um resumo breve e atrativo da vaga." {...field} rows={3} /></FormControl><FormMessage /></FormItem>} />
            <FormField control={form.control} name="detailed_description" render={({ field }) => <FormItem><FormLabel className="text-foreground">Descrição Detalhada</FormLabel><FormControl><ReactQuill theme="snow" value={field.value} onChange={field.onChange} className="bg-card" /></FormControl><FormMessage /></FormItem>} />
            <FormField control={form.control} name="mandatory_requirements" render={({ field }) => <FormItem><FormLabel className="text-foreground">Requisitos Obrigatórios</FormLabel><FormControl><Textarea placeholder="Liste os requisitos essenciais para a vaga." {...field} rows={5} /></FormControl><FormDescription className="text-muted-foreground">Insira um requisito por linha.</FormDescription><FormMessage /></FormItem>} />
            <FormField control={form.control} name="differential_requirements" render={({ field }) => <FormItem><FormLabel className="text-foreground">Diferenciais da vaga</FormLabel><FormControl><Textarea placeholder="Liste os diferenciais que somarão pontos." {...field} rows={5} /></FormControl><FormDescription className="text-muted-foreground">Insira um diferencial por linha.</FormDescription><FormMessage /></FormItem>} />
            <FormField control={form.control} name="benefits" render={({ field }) => <FormItem><FormLabel className="text-foreground">Benefícios da vaga</FormLabel><FormControl><Textarea placeholder="Liste os benefícios oferecidos." {...field} rows={5} /></FormControl><FormDescription className="text-muted-foreground">Insira um benefício por linha.</FormDescription><FormMessage /></FormItem>} />
          </CardContent>
        </Card>

        <Card className="bg-card backdrop-blur-md border border-border shadow-lg rounded-2xl">
          <CardHeader><CardTitle className="text-foreground">Configurações e Visibilidade</CardTitle></CardHeader>
          <CardContent className="space-y-4">
            <div className="grid grid-cols-1 md:grid-cols-2 gap-4">
              <FormField control={form.control} name="salary_min" render={({ field }) => <FormItem><FormLabel className="text-foreground">Faixa Salarial (Mínimo)</FormLabel><FormControl><Input type="number" placeholder="Ex: 5500" {...field} /></FormControl><FormMessage /></FormItem>} />
              <FormField control={form.control} name="salary_max" render={({ field }) => <FormItem><FormLabel className="text-foreground">Faixa Salarial (Máximo)</FormLabel><FormControl><Input type="number" placeholder="Ex: 7000" {...field} /></FormControl><FormMessage /></FormItem>} />
            </div>
            <FormField control={form.control} name="hashtags" render={({ field }) => <FormItem><FormLabel className="text-foreground">Hashtags</FormLabel><FormControl><Input placeholder="react, typescript, nodejs" {...field} /></FormControl><FormDescription className="text-muted-foreground">Separe as hashtags por vírgula.</FormDescription><FormMessage /></FormItem>} />
          </CardContent>
        </Card>

        <div className="flex justify-end gap-2 pt-4">
          <Button type="button" variant="outline" onClick={() => navigate('/connect/jobs')} disabled={isLoading} className="rounded-lg">Cancelar</Button>
          <Button type="submit" disabled={isLoading} className="bg-sollux-red hover:bg-sollux-orange">{isLoading ? 'Salvando...' : (isEditing ? 'Salvar Alterações' : 'Criar Vaga')}</Button>
        </div>
      </form>
    </Form>
  );
};

export default JobFormPage;

import React, { useState, useEffect } from 'react';
import { useForm } from 'react-hook-form';
import { zodResolver } from '@hookform/resolvers/zod';
import * as z from 'zod';
import { Card, CardContent, CardHeader, CardTitle, CardDescription } from '@/components/ui/card';
import { Button } from '@/components/ui/button';
import { Input } from '@/components/ui/input';
import { Dialog, DialogContent, DialogHeader, DialogTitle, DialogFooter, DialogDescription } from '@/components/ui/dialog';
import { Form, FormControl, FormField, FormItem, FormLabel, FormMessage } from '@/components/ui/form';
import { Table, TableBody, TableCell, TableHead, TableHeader, TableRow } from '@/components/ui/table';
import { Plus, Edit, Trash2, Loader2, TrendingUp } from 'lucide-react';
import { supabase } from '@/integrations/supabase/client';
import { showSuccess, showError } from '@/utils/toast';
import { useQuery, useMutation, useQueryClient } from '@tanstack/react-query';
import { useSession } from '@/components/SessionContextProvider';
import { useCompany } from '@/components/CompanyContext';
import { format } from 'date-fns';
import { ptBR } from 'date-fns/locale';
import DatePicker from '@/components/DatePicker';
import { Appointment } from '@/types/appointment';
import KpiApontamentosForm from '@/components/KpiApontamentosForm';
import { useParams, useNavigate } from 'react-router-dom';

// Schema de validação para o formulário de apontamento
const appointmentFormSchema = z.object({
  value: z.coerce.number({
    invalid_type_error: "O valor deve ser um número.",
    required_error: "O valor é obrigatório."
  }).positive({ message: "O valor deve ser positivo." }),
  note: z.string().optional().nullable(),
  appointment_date: z.date({ required_error: "A data do apontamento é obrigatória." }),
});

type AppointmentFormData = z.infer<typeof formSchema>;

const KpiApontamentosPage: React.FC = () => {
  const queryClient = useQueryClient();
  const { user } = useSession();
  const { selectedCompany } = useCompany();
  const navigate = useNavigate();
  const { id: kpiLiberatedIdFromUrl } = useParams<{ id: string }>(); // Obter o ID do KPI Liberado da URL

  const [isFormDialogOpen, setIsFormDialogOpen] = useState(false);
  const [editingAppointment, setEditingAppointment] = useState<Appointment | null>(null);

  // Fetch details of the specific KpiSmartLiberated
  const { data: kpiLiberatedDetails, isLoading: isLoadingKpiLiberatedDetails, error: errorKpiLiberatedDetails } = useQuery<any, Error>({
    queryKey: ['kpiSmartLiberatedDetails', kpiLiberatedIdFromUrl],
    queryFn: async () => {
      if (!kpiLiberatedIdFromUrl || !user?.id) return null; // Retorna null se faltar dados
      const { data, error } = await supabase
        .from('kpi_smarts_liberated')
        .select(`
          id, code, kpi_smart_id,
          kpi_smarts(description, kpi_smart_types(description), kpi_smart_focuses(description), kpi_smart_units(description)),
          execution_user_ids, view_user_ids
        `)
        .eq('id', kpiLiberatedIdFromUrl)
        .eq('user_id', user.id)
        .single();
      if (error) throw error;
      return data;
    },
    enabled: !!kpiLiberatedIdFromUrl && !!user?.id,
    retry: false,
  });

  // Fetch all appointments for the specific kpi_smart_liberated_id
  const { data: appointments, isLoading: isLoadingAppointments, error: errorAppointments } = useQuery<Appointment[], Error>({
    queryKey: ['appointments', kpiLiberatedIdFromUrl, user?.id],
    queryFn: async () => {
      if (!kpiLiberatedIdFromUrl || !user?.id) return [];
      const { data, error } = await supabase
        .from('kpi_apontamentos')
        .select('*')
        .eq('kpi_smart_liberated_id', kpiLiberatedIdFromUrl)
        .order('appointment_date', { ascending: false });
      if (error) throw error;
      return data;
    },
    enabled: !!kpiLiberatedIdFromUrl && !!user?.id,
  });

  // Mutation para criar um novo apontamento
  const createAppointmentMutation = useMutation({
    mutationFn: async (data: AppointmentFormData) => {
      if (!kpiLiberatedIdFromUrl || !user?.id) throw new Error("ID do KPI Smart Liberado ou usuário faltando.");
      const { error } = await supabase.from('kpi_apontamentos').insert({
        kpi_smart_liberated_id: kpiLiberatedIdFromUrl,
        value: data.value,
        note: data.note || null,
        appointment_date: format(data.appointment_date, 'yyyy-MM-dd'),
      });
      if (error) throw error;
    },
    onSuccess: () => {
      queryClient.invalidateQueries({ queryKey: ['appointments', kpiLiberatedIdFromUrl, user?.id] });
      showSuccess('Apontamento registrado com sucesso!');
      setIsFormDialogOpen(false);
      setEditingAppointment(null);
    },
    onError: (error: Error) => {
      showError(`Erro ao registrar apontamento: ${error.message}`);
    },
  });

  // Mutation para editar um apontamento
  const updateAppointmentMutation = useMutation({
    mutationFn: async (data: AppointmentFormData) => {
      if (!editingAppointment?.id) throw new Error("ID do apontamento está faltando.");
      const { error } = await supabase.from('kpi_apontamentos').update({
        value: data.value,
        note: data.note || null,
        appointment_date: format(data.appointment_date, 'yyyy-MM-dd'),
      }).eq('id', editingAppointment.id);
      if (error) throw error;
    },
    onSuccess: () => {
      queryClient.invalidateQueries({ queryKey: ['appointments', kpiLiberatedIdFromUrl, user?.id] });
      showSuccess('Apontamento atualizado com sucesso!');
      setIsFormDialogOpen(false);
      setEditingAppointment(null);
    },
    onError: (error: Error) => {
      showError(`Erro ao atualizar apontamento: ${error.message}`);
    },
  });

  // Mutation para excluir um apontamento
  const deleteAppointmentMutation = useMutation({
    mutationFn: async (id: string) => {
      const { error } = await supabase.from('kpi_apontamentos').delete().eq('id', id);
      if (error) throw error;
    },
    onSuccess: () => {
      queryClient.invalidateQueries({ queryKey: ['appointments', kpiLiberatedIdFromUrl, user?.id] });
      showSuccess('Apontamento excluído com sucesso!');
    },
    onError: (error: Error) => {
      showError(`Erro ao excluir apontamento: ${error.message}`);
    },
  });

  const handleFormSubmit = (data: AppointmentFormData) => {
    if (editingAppointment) {
      updateAppointmentMutation.mutate(data);
    } else {
      createAppointmentMutation.mutate(data);
    }
  };

  const handleAddClick = () => {
    setEditingAppointment(null);
    setIsFormDialogOpen(true);
  };

  const handleEditClick = (appointment: Appointment) => {
    setEditingAppointment(appointment);
    setIsFormDialogOpen(true);
  };

  const handleDeleteClick = (id: string) => {
    if (window.confirm('Tem certeza que deseja excluir este apontamento?')) {
      deleteAppointmentMutation.mutate(id);
    }
  };

  const isMutating = createAppointmentMutation.isPending || updateAppointmentMutation.isPending || deleteAppointmentMutation.isPending;

  if (isLoadingKpiLiberatedDetails || isLoadingAppointments) {
    return <div className="text-center text-muted-foreground py-8">Carregando dados...</div>;
  }

  if (errorKpiLiberatedDetails || errorAppointments) {
    return <div className="text-center text-destructive">Erro ao carregar dados: {errorKpiLiberatedDetails?.message || errorAppointments?.message}</div>;
  }

  if (!kpiLiberatedDetails) {
    return (
      <div className="flex flex-col items-center justify-center min-h-[calc(100vh-10rem)]">
        <Card className="w-full max-w-md bg-card backdrop-blur-md rounded-2xl shadow-lg p-6 text-center border border-border">
          <CardHeader>
            <CardTitle className="text-2xl font-bold text-sollux-red">KPI Smart Liberado não encontrado</CardTitle>
          </CardHeader>
          <CardContent>
            <p className="text-muted-foreground">O KPI Smart Liberado que você está tentando gerenciar não existe ou você não tem permissão.</p>
            <Button onClick={() => navigate('/ops/shift')} className="mt-4 rounded-lg bg-sollux-red hover:bg-sollux-orange">
              Voltar para a lista de KPIs Liberados
            </Button>
          </CardContent>
        </Card>
      </div>
    );
  }

  return (
    <div className="space-y-6">
      <Card className="bg-card backdrop-blur-md border border-border shadow-lg rounded-2xl">
        <CardHeader className="flex flex-row items-center justify-between">
          <div>
            <CardTitle className="text-foreground uppercase font-bold">Apontamentos para: {kpiLiberatedDetails.kpi_smarts?.description || 'KPI Smart Desconhecido'}</CardTitle>
            <CardDescription className="text-muted-foreground">
              Código: {kpiLiberatedDetails.code} | Tipo: {kpiLiberatedDetails.kpi_smarts?.kpi_smart_types?.description || 'N/A'}
            </CardDescription>
          </div>
          <Button onClick={handleAddClick} className="bg-sollux-red hover:bg-sollux-red/90 text-white rounded-lg">
            <Plus className="mr-2 h-4 w-4" /> Adicionar Apontamento
          </Button>
        </CardHeader>
        <CardContent>
          <Table>
            <TableHeader>
              <TableRow>
                <TableHead className="text-foreground">Valor</TableHead>
                <TableHead className="text-foreground">Nota</TableHead>
                <TableHead className="text-foreground">Data</TableHead>
                <TableHead className="text-right text-foreground">Ações</TableHead>
              </TableRow>
            </TableHeader>
            <TableBody>
              {appointments?.length === 0 ? (
                <TableRow>
                  <TableCell colSpan={4} className="text-center text-muted-foreground">
                    Nenhum apontamento registrado para este KPI Smart Liberado.
                  </TableCell>
                </TableRow>
              ) : (
                appointments?.map((appt) => (
                  <TableRow key={appt.id}>
                    <TableCell className="font-medium text-foreground">{appt.value !== null ? appt.value.toLocaleString('pt-BR', { minimumFractionDigits: 2, maximumFractionDigits: 2 }) : 'N/A'}</TableCell>
                    <TableCell className="text-muted-foreground">{appt.note || 'Sem nota'}</TableCell>
                    <TableCell className="text-muted-foreground">
                      {appt.appointment_date ? format(new Date(appt.appointment_date), 'dd/MM/yyyy', { locale: ptBR }) : 'N/A'}
                    </TableCell>
                    <TableCell className="text-right">
                      <Button
                        variant="ghost"
                        size="sm"
                        onClick={() => handleEditClick(appt)}
                        className="mr-2 text-foreground hover:bg-accent rounded-lg"
                        disabled={isMutating}
                      >
                        <Edit className="h-4 w-4" />
                      </Button>
                      <Button
                        variant="destructive"
                        size="sm"
                        onClick={() => handleDeleteClick(appt.id)}
                        className="bg-sollux-red hover:bg-red-700 text-white rounded-lg"
                        disabled={isMutating}
                      >
                        <Trash2 className="h-4 w-4" />
                      </Button>
                    </TableCell>
                  </TableRow>
                ))
              )}
            </TableBody>
          </Table>
        </CardContent>
      </Card>

      <KpiApontamentosForm
        open={isFormDialogOpen}
        onOpenChange={setIsFormDialogOpen}
        onSubmit={handleFormSubmit}
        initialData={editingAppointment ? {
          value: editingAppointment.value?.toString() || '',
          note: editingAppointment.note || '',
          appointment_date: new Date(editingAppointment.appointment_date),
        } : null}
        isLoading={isMutating}
        kpiLiberatedId={kpiLiberatedIdFromUrl!}
      />
    </div>
  );
};

export default KpiApontamentosPage;

import React, { useState, useEffect, useMemo } from 'react';
import { useForm } from 'react-hook-form';
import { zodResolver } from '@hookform/resolvers/zod';
import * as z from 'zod';
import { Card, CardContent, CardHeader, CardTitle } from '@/components/ui/card';
import { Button } from '@/components/ui/button';
import { Input } from '@/components/ui/input';
import { Dialog, DialogContent, DialogHeader, DialogTitle, DialogFooter } from '@/components/ui/dialog';
import { Form, FormControl, FormField, FormItem, FormLabel, FormMessage } from '@/components/ui/form';
import { Table, TableBody, TableCell, TableHead, TableHeader, TableRow } from '@/components/ui/table';
import { Plus, Edit, Trash2 } from 'lucide-react';
import { supabase } from '@/integrations/supabase/client';
import { showSuccess, showError } from '@/utils/toast';
import { Kpi, KpiFormData } from '@/types/kpi';
import { Pillar } from '@/types/pillar';
import { PillarBlock } from '@/types/pillarBlock';
import { Tag } from '@/types/tag'; // Importar o tipo Tag
import { useQuery, useMutation, useQueryClient } from '@tanstack/react-query';
import { useSession } from '@/components/SessionContextProvider';
import { Textarea } from '@/components/ui/textarea';
import { Select, SelectContent, SelectItem, SelectTrigger, SelectValue } from '@/components/ui/select';
import MultiSelect, { MultiSelectOption } from '@/components/MultiSelect'; // Importar MultiSelect
import { Label } from '@/components/ui/label'; // Importar Label

const formSchema = z.object({
  pillar_id: z.string().min(1, { message: 'O pilar é obrigatório.' }),
  pillar_block_id: z.string().min(1, { message: 'O bloco é obrigatório.' }),
  question: z.string().min(1, { message: 'A pergunta é obrigatória.' }),
  tags: z.array(z.string()).optional(), // Alterado para array de strings para o MultiSelect
});

const KpiManagementPage: React.FC = () => {
  const queryClient = useQueryClient();
  const { user } = useSession();
  const [isDialogOpen, setIsDialogOpen] = useState(false);
  const [editingKpi, setEditingKpi] = useState<Kpi | null>(null);

  // Estados para os filtros
  const [selectedPillarFilter, setSelectedPillarFilter] = useState<string>('all');
  const [selectedBlockFilter, setSelectedBlockFilter] = useState<string>('all');

  const form = useForm<z.infer<typeof formSchema>>({ // Usar z.infer<typeof formSchema> para o tipo do form
    resolver: zodResolver(formSchema),
    defaultValues: {
      pillar_id: '',
      pillar_block_id: '',
      question: '',
      tags: [], // Inicializar como array vazio
    },
  });

  const selectedPillarId = form.watch('pillar_id');

  useEffect(() => {
    if (editingKpi) {
      form.reset({
        pillar_id: editingKpi.pillar_id || '',
        pillar_block_id: editingKpi.pillar_block_id || '',
        question: editingKpi.question,
        tags: editingKpi.tags || [], // Carregar tags existentes
      });
    } else {
      form.reset({
        pillar_id: '',
        pillar_block_id: '',
        question: '',
        tags: [],
      });
    }
  }, [editingKpi, form, isDialogOpen]);

  const { data: kpis, isLoading: isLoadingKpis, error: errorKpis } = useQuery<Kpi[], Error>({
    queryKey: ['kpis', user?.id, selectedPillarFilter, selectedBlockFilter], // Adicionado filtros ao queryKey
    queryFn: async () => {
      if (!user?.id) return [];
      let query = supabase
        .from('kpis')
        .select('*, pillars(description, pillar_types(description)), pillar_blocks(name)')
        .eq('user_id', user.id);
      
      // Aplicar filtros
      if (selectedPillarFilter !== 'all') {
        query = query.eq('pillar_id', selectedPillarFilter);
      }
      if (selectedBlockFilter !== 'all') {
        query = query.eq('pillar_block_id', selectedBlockFilter);
      }

      query = query.order('created_at', { ascending: false });
      const { data, error } = await query;
      if (error) throw error;
      return data;
    },
    enabled: !!user?.id,
  });

  const { data: pillars, isLoading: isLoadingPillars } = useQuery<Pillar[], Error>({
    queryKey: ['pillarsListForKpi', user?.id],
    queryFn: async () => {
      if (!user?.id) return [];
      const { data, error } = await supabase
        .from('pillars')
        .select('*, pillar_types(description)')
        .eq('user_id', user.id)
        .order('description', { ascending: true });
      if (error) throw error;
      return data;
    },
    enabled: !!user?.id,
  });

  const { data: pillarBlocks, isLoading: isLoadingPillarBlocks } = useQuery<PillarBlock[], Error>({
    queryKey: ['pillarBlocksListForKpi', user?.id],
    queryFn: async () => {
      if (!user?.id) return [];
      const { data, error } = await supabase
        .from('pillar_blocks')
        .select('*')
        .eq('user_id', user.id)
        .order('name', { ascending: true });
      if (error) throw error;
      return data;
    },
    enabled: !!user?.id,
  });

  const { data: tags, isLoading: isLoadingTags } = useQuery<Tag[], Error>({
    queryKey: ['tagsForKpi', user?.id],
    queryFn: async () => {
      if (!user?.id) return [];
      const { data, error } = await supabase
        .from('tags')
        .select('*')
        .eq('user_id', user.id)
        .order('name', { ascending: true });
      if (error) throw error;
      return data;
    },
    enabled: !!user?.id,
  });

  const tagOptions: MultiSelectOption[] = useMemo(() => {
    return tags?.map(tag => ({ value: tag.name, label: tag.name })) || [];
  }, [tags]);

  const filteredPillarBlocks = useMemo(() => {
    if (!pillarBlocks || !selectedPillarId) return [];
    return pillarBlocks.filter(block => block.pillar_id === selectedPillarId);
  }, [pillarBlocks, selectedPillarId]);

  // Filtra os blocos para o dropdown de filtro
  const filteredBlocksForFilter = useMemo(() => {
    if (!pillarBlocks) return [];
    if (selectedPillarFilter === 'all') return pillarBlocks;
    return pillarBlocks.filter(block => block.pillar_id === selectedPillarFilter);
  }, [pillarBlocks, selectedPillarFilter]);

  const selectedPillar = pillars?.find(p => p.id === selectedPillarId);
  const selectedPillarTypeName = (selectedPillar as any)?.pillar_types?.description || 'N/A';

  const mutationOptions = {
    onSuccess: () => {
      queryClient.invalidateQueries({ queryKey: ['kpis', user?.id] });
      setIsDialogOpen(false);
      setEditingKpi(null);
    },
    onError: (error: Error) => {
      showError(`Erro: ${error.message}`);
    },
  };

  const createKpiMutation = useMutation({
    mutationFn: async (data: z.infer<typeof formSchema>) => {
      if (!user?.id) throw new Error("Usuário não autenticado.");
      const { data: newKpi, error } = await supabase
        .from('kpis')
        .insert({
          pillar_id: data.pillar_id,
          pillar_block_id: data.pillar_block_id,
          question: data.question,
          tags: data.tags && data.tags.length > 0 ? data.tags : null, // Salvar tags
          user_id: user.id,
        })
        .select()
        .single();
      if (error) throw error;
      return newKpi;
    },
    ...mutationOptions,
    onSuccess: () => {
      mutationOptions.onSuccess();
      showSuccess('KPI criado com sucesso!');
    },
  });

  const updateKpiMutation = useMutation({
    mutationFn: async (data: z.infer<typeof formSchema>) => {
      if (!editingKpi?.id) throw new Error("ID do KPI está faltando.");
      const { data: updatedKpi, error } = await supabase
        .from('kpis')
        .update({
          pillar_id: data.pillar_id,
          pillar_block_id: data.pillar_block_id,
          question: data.question,
          tags: data.tags && data.tags.length > 0 ? data.tags : null, // Atualizar tags
        })
        .eq('id', editingKpi.id)
        .eq('user_id', user?.id)
        .select()
        .single();
      if (error) throw error;
      return updatedKpi;
    },
    ...mutationOptions,
    onSuccess: () => {
      mutationOptions.onSuccess();
      showSuccess('KPI atualizado com sucesso!');
    },
  });

  const deleteKpiMutation = useMutation({
    mutationFn: async (id: string) => {
      if (!user?.id) throw new Error("Usuário não autenticado.");
      const { error, count } = await supabase
        .from('kpis')
        .delete()
        .eq('id', id)
        .eq('user_id', user.id);
      
      if (error) {
        throw error;
      }
      if (count === 0) {
        throw new Error("KPI não encontrado ou você não tem permissão para excluí-lo.");
      }
    },
    ...mutationOptions,
    onSuccess: () => {
      mutationOptions.onSuccess();
      showSuccess('KPI excluído com sucesso!');
    },
  });

  const onSubmit = (data: z.infer<typeof formSchema>) => {
    if (editingKpi) {
      updateKpiMutation.mutate(data);
    } else {
      createKpiMutation.mutate(data);
    }
  };

  const handleAddClick = () => {
    setEditingKpi(null);
    setIsDialogOpen(true);
  };

  const handleEditClick = (kpi: Kpi) => {
    setEditingKpi(kpi);
    setIsDialogOpen(true);
  };

  const handleDeleteClick = (id: string) => {
    if (window.confirm('Tem certeza que deseja excluir este KPI?')) {
      deleteKpiMutation.mutate(id);
    }
  };

  const isMutating = createKpiMutation.isPending || updateKpiMutation.isPending || deleteKpiMutation.isPending;
  const isLoadingPage = isLoadingKpis || isLoadingPillars || isLoadingPillarBlocks || isLoadingTags;

  if (isLoadingPage) {
    return <div className="text-center text-muted-foreground">Carregando KPIs...</div>;
  }

  if (errorKpis) {
    return <div className="text-center text-destructive">Erro ao carregar KPIs: {errorKpis.message}</div>;
  }

  return (
    <div className="space-y-6">
      <Card className="bg-card backdrop-blur-md border border-border shadow-lg rounded-2xl">
        <CardHeader className="flex flex-row items-center justify-between">
          <CardTitle className="text-foreground uppercase font-bold">Gerenciar Perguntas para KPIs de Diagnóstico</CardTitle>
          <Button onClick={handleAddClick} className="bg-sollux-red hover:bg-sollux-red/90 text-white rounded-lg">
            <Plus className="mr-2 h-4 w-4" /> Adicionar Pergunta
          </Button>
        </CardHeader>
        <CardContent>
          <div className="grid grid-cols-1 md:grid-cols-2 gap-4 mb-6">
            {/* Filtro por Pilar */}
            <div>
              <Label htmlFor="pillar-filter" className="text-foreground">Filtrar por Pilar</Label>
              <Select
                value={selectedPillarFilter}
                onValueChange={(value) => {
                  setSelectedPillarFilter(value);
                  setSelectedBlockFilter('all'); // Resetar filtro de bloco ao mudar o pilar
                }}
                disabled={isLoadingPillars}
              >
                <SelectTrigger id="pillar-filter" className="rounded-lg">
                  <SelectValue placeholder="Todos os Pilares" />
                </SelectTrigger>
                <SelectContent>
                  <SelectItem value="all">Todos os Pilares</SelectItem>
                  {pillars?.map((pillar) => (
                    <SelectItem key={pillar.id} value={pillar.id}>
                      {pillar.description}
                    </SelectItem>
                  ))}
                </SelectContent>
              </Select>
            </div>

            {/* Filtro por Bloco */}
            <div>
              <Label htmlFor="block-filter" className="text-foreground">Filtrar por Bloco</Label>
              <Select
                value={selectedBlockFilter}
                onValueChange={setSelectedBlockFilter}
                disabled={isLoadingPillarBlocks || (selectedPillarFilter !== 'all' && filteredBlocksForFilter.length === 0)}
              >
                <SelectTrigger id="block-filter" className="rounded-lg">
                  <SelectValue placeholder="Todos os Blocos" />
                </SelectTrigger>
                <SelectContent>
                  <SelectItem value="all">Todos os Blocos</SelectItem>
                  {filteredBlocksForFilter.length === 0 ? (
                    <SelectItem value="no-blocks" disabled>Nenhum bloco para este pilar</SelectItem>
                  ) : (
                    filteredBlocksForFilter.map((block) => (
                      <SelectItem key={block.id} value={block.id}>
                        {block.name}
                      </SelectItem>
                    ))
                  )}
                </SelectContent>
              </Select>
            </div>
          </div>

          <Table>
            <TableHeader>
              <TableRow>
                <TableHead className="text-foreground">Pilar</TableHead>
                <TableHead className="text-foreground">Bloco</TableHead>
                <TableHead className="text-foreground">Pergunta</TableHead>
                <TableHead className="text-foreground">Tags</TableHead> {/* Nova coluna para Tags */}
                <TableHead className="text-right text-foreground">Ações</TableHead>
              </TableRow>
            </TableHeader>
            <TableBody>
              {kpis?.length === 0 ? (
                <TableRow>
                  <TableCell colSpan={5} className="text-center text-muted-foreground"> {/* Colspan ajustado */}
                    Nenhuma pergunta de KPI encontrada com os filtros aplicados.
                  </TableCell>
                </TableRow>
              ) : (
                kpis?.map((kpi) => (
                  <TableRow key={kpi.id}>
                    <TableCell className="text-muted-foreground">
                      {(kpi as any).pillars?.description || 'N/A'}
                    </TableCell>
                    <TableCell className="text-muted-foreground">
                      {(kpi as any).pillar_blocks?.name || 'N/A'}
                    </TableCell>
                    <TableCell className="font-medium text-foreground">{kpi.question}</TableCell>
                    <TableCell className="text-muted-foreground"> {/* Exibir Tags */}
                      {kpi.tags && kpi.tags.length > 0 ? kpi.tags.join(', ') : 'N/A'}
                    </TableCell>
                    <TableCell className="text-right flex justify-end items-center gap-1">
                      <Button
                        variant="ghost"
                        size="sm"
                        onClick={() => handleEditClick(kpi)}
                        className="mr-2 text-foreground hover:bg-accent rounded-lg"
                        disabled={isMutating}
                      >
                        <Edit className="h-4 w-4" />
                      </Button>
                      <Button
                        variant="destructive"
                        size="sm"
                        onClick={() => handleDeleteClick(kpi.id)}
                        className="bg-sollux-red hover:bg-red-700 text-white rounded-lg"
                        disabled={isMutating}
                      >
                        <Trash2 className="h-4 w-4" />
                      </Button>
                    </TableCell>
                  </TableRow>
                ))
              )}
            </TableBody>
          </Table>
        </CardContent>
      </Card>

      <Dialog open={isDialogOpen} onOpenChange={setIsDialogOpen}>
        <DialogContent className="sm:max-w-lg bg-card backdrop-blur-md rounded-2xl shadow-lg border border-border">
          <DialogHeader>
            <DialogTitle className="text-foreground">{editingKpi ? 'Editar Pergunta de KPI' : 'Adicionar Nova Pergunta de KPI'}</DialogTitle>
          </DialogHeader>
          <Form {...form}>
            <form onSubmit={form.handleSubmit(onSubmit)} className="space-y-4">
              <FormField
                control={form.control}
                name="pillar_id"
                render={({ field }) => (
                  <FormItem>
                    <FormLabel className="text-foreground">Pilar</FormLabel>
                    <Select onValueChange={(value) => {
                      field.onChange(value);
                      form.setValue('pillar_block_id', ''); // Reset pillar block when pillar changes
                    }} value={field.value} disabled={isLoadingPillars}>
                      <FormControl>
                        <SelectTrigger className="rounded-lg">
                          <SelectValue placeholder="Selecione um pilar" />
                        </SelectTrigger>
                      </FormControl>
                      <SelectContent>
                        {pillars?.length === 0 ? (
                          <SelectItem value="no-pillars" disabled>Nenhum pilar cadastrado</SelectItem>
                        ) : (
                          pillars?.map((pillar) => (
                            pillar.id && pillar.id !== '' ? (
                              <SelectItem key={pillar.id} value={pillar.id}>
                                {pillar.description}
                              </SelectItem>
                            ) : null
                          ))
                        )}
                      </SelectContent>
                    </Select>
                    <FormMessage />
                  </FormItem>
                )}
              />
              <FormItem>
                <FormLabel className="text-foreground">Tipo do Pilar</FormLabel>
                <Input value={selectedPillarTypeName} readOnly className="rounded-lg bg-muted text-muted-foreground" />
              </FormItem>
              <FormField
                control={form.control}
                name="pillar_block_id"
                render={({ field }) => (
                  <FormItem>
                    <FormLabel className="text-foreground">Bloco</FormLabel>
                    <Select onValueChange={field.onChange} value={field.value} disabled={!selectedPillarId || isLoadingPillarBlocks || filteredPillarBlocks.length === 0}>
                      <FormControl>
                        <SelectTrigger className="rounded-lg">
                          <SelectValue placeholder="Selecione um bloco" />
                        </SelectTrigger>
                      </FormControl>
                      <SelectContent>
                        {filteredPillarBlocks.length === 0 ? (
                          <SelectItem value="no-blocks" disabled>Nenhum bloco para este pilar</SelectItem>
                        ) : (
                          filteredPillarBlocks.map((block) => (
                            block.id && block.id !== '' ? (
                              <SelectItem key={block.id} value={block.id}>
                                {block.name}
                              </SelectItem>
                            ) : null
                          ))
                        )}
                      </SelectContent>
                    </Select>
                    <FormMessage />
                  </FormItem>
                )}
              />
              <FormField
                control={form.control}
                name="question"
                render={({ field }) => (
                  <FormItem>
                    <FormLabel className="text-foreground">Pergunta</FormLabel>
                    <FormControl>
                      <Textarea placeholder="Ex: Quão satisfeito você está com o produto?" {...field} className="rounded-lg" />
                    </FormControl>
                    <FormMessage />
                  </FormItem>
                )}
              />
              <FormField
                control={form.control}
                name="tags"
                render={({ field }) => (
                  <FormItem>
                    <FormLabel className="text-foreground">Tags (Opcional)</FormLabel>
                    <FormControl>
                      <MultiSelect
                        options={tagOptions}
                        selected={field.value || []}
                        onChange={field.onChange}
                        placeholder="Selecione as tags..."
                        className="rounded-lg"
                      />
                    </FormControl>
                    <FormMessage />
                  </FormItem>
                )}
              />
              <DialogFooter className="flex justify-end gap-2 pt-4">
                <Button type="button" variant="outline" onClick={() => setIsDialogOpen(false)} disabled={isMutating} className="rounded-lg">
                  Cancelar
                </Button>
                <Button type="submit" disabled={isMutating} className="rounded-lg bg-sollux-red hover:bg-sollux-orange">
                  {editingKpi ? 'Salvar Alterações' : 'Adicionar Pergunta'}
                </Button>
              </DialogFooter>
            </form>
          </Form>
        </DialogContent>
      </Dialog>
    </div>
  );
};

export default KpiManagementPage;

import React, { useState, useEffect, useMemo } from 'react';
import { useForm } from 'react-hook-form';
import { zodResolver } from '@hookform/resolvers/zod';
import * as z from 'zod';
import { Card, CardContent, CardHeader, CardTitle, CardDescription } from '@/components/ui/card';
import { Button } from '@/components/ui/button';
import { Input } from '@/components/ui/input';
import { Form, FormControl, FormField, FormItem, FormLabel, FormMessage } from '@/components/ui/form';
import { supabase } from '@/integrations/supabase/client';
import { showSuccess, showError } from '@/utils/toast';
import { KpiSmartLiberated, KpiSmartLiberatedFormData } from '@/types/kpiSmartLiberated';
import { KpiSmart } from '@/types/kpiSmart';
import { Pillar } from '@/types/pillar';
import { KpiSmartFrequency } from '@/types/kpiSmartFrequency';
import { KpiSmartStatus } from '@/types/kpiSmartStatus';
import { useQuery, useMutation, useQueryClient } from '@tanstack/react-query';
import { useSession } from '@/components/SessionContextProvider';
import { Select, SelectContent, SelectItem, SelectTrigger, SelectValue } from '@/components/ui/select';
import { useNavigate, useParams } from 'react-router-dom';
import { Loader2 } from 'lucide-react';
import MultiSelect, { MultiSelectOption } from '@/components/MultiSelect';
import DatePicker from '@/components/DatePicker';
import { format } from 'date-fns';
import { BasicProfileInfo } from '@/types/profile';
import { useCompany } from '@/components/CompanyContext';
import { Label } from '@/components/ui/label';

// Helper para converter string vazia para undefined para campos opcionais de número
const emptyStringToUndefined = z.preprocess(
  (val) => (val === "" ? undefined : val),
  z.any()
);

const formSchema = z.object({
  kpi_smart_id: z.string().min(1, { message: 'O KPI Smart é obrigatório.' }),
  pillar_id: z.string().min(1, { message: 'O pilar é obrigatório.' }),
  execution_user_ids: z.array(z.string()).optional().nullable(),
  view_user_ids: z.array(z.string()).optional().nullable(),
  kpi_smart_frequency_id: z.string().min(1, { message: 'A frequência de monitoramento é obrigatória.' }),
  kpi_smart_status_id: z.string().min(1, { message: 'O status é obrigatório.' }),

  // Campos para tipo 'Quantitativo'
  logical_comparator: z.string().optional().nullable(),
  base_value: emptyStringToUndefined.pipe(z.coerce.number().optional().nullable()),
  target_value: emptyStringToUndefined.pipe(z.coerce.number().optional().nullable()),
  deadline_date: z.date().optional().nullable(),

  // Campos para tipo 'Marco'
  planned_delivery_date: z.date().optional().nullable(),
  actual_delivery_date: z.date().optional().nullable(),
  progress_percentage: emptyStringToUndefined.pipe(z.coerce.number().min(0).max(100).optional().nullable()),

  // Campos Frequência
  planned_frequency: z.string().optional().nullable(),
  planned_executions: emptyStringToUndefined.pipe(z.coerce.number().int().positive().optional().nullable()),
  performed_executions: emptyStringToUndefined.pipe(z.coerce.number().int().positive().optional().nullable()),

  // Campos Intervalo
  min_value: emptyStringToUndefined.pipe(z.coerce.number().optional().nullable()),
  max_value: emptyStringToUndefined.pipe(z.coerce.number().optional().nullable()),
  current_value: emptyStringToUndefined.pipe(z.coerce.number().optional().nullable()),
});

const KpiSmartLiberatedFormPage: React.FC = () => {
  const queryClient = useQueryClient();
  const { user } = useSession();
  const { selectedCompany } = useCompany();
  const navigate = useNavigate();
  const { id: kpiSmartLiberatedId } = useParams<{ id: string }>();
  const isEditing = !!kpiSmartLiberatedId;

  const [selectedPillarIdForKpiSmart, setSelectedPillarIdForKpiSmart] = useState<string>('');
  const [selectedKpiSmartDetails, setSelectedKpiSmartDetails] = useState<KpiSmart | null>(null);

  const form = useForm<z.infer<typeof formSchema>>({
    resolver: zodResolver(formSchema),
    defaultValues: {
      kpi_smart_id: '',
      pillar_id: '',
      execution_user_ids: [],
      view_user_ids: [],
      kpi_smart_frequency_id: '',
      kpi_smart_status_id: '',
      logical_comparator: null,
      base_value: null,
      target_value: null,
      deadline_date: null,
      planned_delivery_date: null,
      actual_delivery_date: null,
      progress_percentage: null,
      planned_frequency: null,
      planned_executions: null,
      performed_executions: null,
      min_value: null,
      max_value: null,
      current_value: null,
    },
  });

  const { data: editingKpiSmartLiberated, isLoading: isLoadingEditingKpiSmartLiberated } = useQuery<KpiSmartLiberated, Error>({
    queryKey: ['kpiSmartLiberated', kpiSmartLiberatedId],
    queryFn: async () => {
      if (!kpiSmartLiberatedId || !user?.id) throw new Error("ID do KPI Smart Liberado ou usuário faltando.");
      const { data, error } = await supabase
        .from('kpi_smarts_liberated')
        .select(`
          *,
          kpi_smarts(id, description, pillar_id, user_id, code, kpi_smart_type_id, kpi_smart_action_verb_id, kpi_smart_focus_id, kpi_smart_unit_id, status, created_at, kpi_smart_types(description, code), kpi_smart_focuses(description), kpi_smart_units(description)),
          kpi_smart_frequencies(description),
          kpi_smart_statuses(description, id)
        `)
        .eq('id', kpiSmartLiberatedId)
        .eq('user_id', user.id)
        .single();
      if (error) throw error;
      return {
        ...data,
        kpi_smarts: Array.isArray(data.kpi_smarts) ? data.kpi_smarts[0] : data.kpi_smarts,
        kpi_smart_frequencies: Array.isArray(data.kpi_smart_frequencies) ? data.kpi_smart_frequencies[0] : data.kpi_smart_frequencies,
        kpi_smart_statuses: Array.isArray(data.kpi_smart_statuses) ? data.kpi_smart_statuses[0] : data.kpi_smart_statuses,
      };
    },
    enabled: isEditing && !!user?.id,
    retry: false,
  });

  useEffect(() => {
    if (isEditing && editingKpiSmartLiberated) {
      const kpiSmartPillarId = (editingKpiSmartLiberated.kpi_smarts as any)?.pillar_id || '';
      setSelectedPillarIdForKpiSmart(kpiSmartPillarId);
      
      const fetchKpiSmartDetails = async () => {
        if (editingKpiSmartLiberated.kpi_smart_id) {
          const { data: kpiDetails, error } = await supabase
            .from('kpi_smarts')
            .select('id, description, pillar_id, user_id, code, kpi_smart_type_id, kpi_smart_action_verb_id, kpi_smart_focus_id, kpi_smart_unit_id, status, created_at, kpi_smart_types(description, code), kpi_smart_focuses(description), kpi_smart_units(description)')
            .eq('id', editingKpiSmartLiberated.kpi_smart_id)
            .single();
          if (error) {
            console.error("Erro ao buscar detalhes do KPI Smart:", error);
          } else {
            // Ensure kpiDetails conforms to KpiSmart type before setting state
            if (kpiDetails) {
              setSelectedKpiSmartDetails({
                ...kpiDetails,
                user_id: kpiDetails.user_id || '', // Provide default values if missing
                code: kpiDetails.code || 0,
                kpi_smart_type_id: kpiDetails.kpi_smart_type_id || '',
                kpi_smart_action_verb_id: kpiDetails.kpi_smart_action_verb_id || '',
                kpi_smart_focus_id: kpiDetails.kpi_smart_focus_id || '',
                kpi_smart_unit_id: kpiDetails.kpi_smart_unit_id || '',
                status: kpiDetails.status || 'active',
                created_at: kpiDetails.created_at || new Date().toISOString(),
                // Ensure nested objects are correctly typed or handle potential nulls
                kpi_smart_types: kpiDetails.kpi_smart_types ? (Array.isArray(kpiDetails.kpi_smart_types) ? kpiDetails.kpi_smart_types[0] : kpiDetails.kpi_smart_types) : null,
                kpi_smart_focuses: kpiDetails.kpi_smart_focuses ? (Array.isArray(kpiDetails.kpi_smart_focuses) ? kpiDetails.kpi_smart_focuses[0] : kpiDetails.kpi_smart_focuses) : null,
                kpi_smart_units: kpiDetails.kpi_smart_units ? (Array.isArray(kpiDetails.kpi_smart_units) ? kpiDetails.kpi_smart_units[0] : kpiDetails.kpi_smart_units) : null,
              });
            }
          }
        }
      };

      fetchKpiSmartDetails();

      const timer = setTimeout(() => {
        form.reset({
          kpi_smart_id: editingKpiSmartLiberated.kpi_smart_id,
          pillar_id: kpiSmartPillarId,
          execution_user_ids: editingKpiSmartLiberated.execution_user_ids || [],
          view_user_ids: editingKpiSmartLiberated.view_user_ids || [],
          kpi_smart_frequency_id: editingKpiSmartLiberated.kpi_smart_frequency_id || '',
          kpi_smart_status_id: editingKpiSmartLiberated.kpi_smart_status_id || '',
          
          logical_comparator: editingKpiSmartLiberated.logical_comparator || null,
          base_value: editingKpiSmartLiberated.base_value || null,
          target_value: editingKpiSmartLiberated.target_value || null,
          deadline_date: editingKpiSmartLiberated.deadline_date ? new Date(editingKpiSmartLiberated.deadline_date + 'T00:00:00') : null,

          planned_delivery_date: editingKpiSmartLiberated.planned_delivery_date ? new Date(editingKpiSmartLiberated.planned_delivery_date + 'T00:00:00') : null,
          actual_delivery_date: editingKpiSmartLiberated.actual_delivery_date ? new Date(editingKpiSmartLiberated.actual_delivery_date + 'T00:00:00') : null,
          progress_percentage: editingKpiSmartLiberated.progress_percentage || null,

          planned_frequency: editingKpiSmartLiberated.planned_frequency || null,
          planned_executions: editingKpiSmartLiberated.planned_executions || null,
          performed_executions: editingKpiSmartLiberated.performed_executions || null,

          min_value: editingKpiSmartLiberated.min_value || null,
          max_value: editingKpiSmartLiberated.max_value || null,
          current_value: editingKpiSmartLiberated.current_value || null,
        });
      }, 100);
      return () => clearTimeout(timer);
    } else if (!isEditing) {
      form.reset({
        kpi_smart_id: '',
        pillar_id: '',
        execution_user_ids: [],
        view_user_ids: [],
        kpi_smart_frequency_id: '',
        kpi_smart_status_id: '',
        logical_comparator: null,
        base_value: null,
        target_value: null,
        deadline_date: null,
        planned_delivery_date: null,
        actual_delivery_date: null,
        progress_percentage: null,
        planned_frequency: null,
        planned_executions: null,
        performed_executions: null,
        min_value: null,
        max_value: null,
        current_value: null,
      });
      setSelectedPillarIdForKpiSmart('');
      setSelectedKpiSmartDetails(null);
    }
  }, [isEditing, editingKpiSmartLiberated, form]);

  const { data: kpiSmarts, isLoading: isLoadingKpiSmarts } = useQuery<KpiSmart[], Error>({
    queryKey: ['kpiSmartsListForLiberatedForm', user?.id, selectedPillarIdForKpiSmart],
    queryFn: async () => {
      if (!user?.id || !selectedPillarIdForKpiSmart) return [];
      const { data, error } = await supabase
        .from('kpi_smarts')
        .select('id, description, pillar_id, user_id, code, kpi_smart_type_id, kpi_smart_action_verb_id, kpi_smart_focus_id, kpi_smart_unit_id, status, created_at, kpi_smart_types(description, code), kpi_smart_focuses(description), kpi_smart_units(description)')
        .eq('user_id', user.id)
        .eq('status', 'active')
        .eq('pillar_id', selectedPillarIdForKpiSmart)
        .order('description', { ascending: true });
      if (error) throw error;
      // Ensure the returned data matches the KpiSmart type, including nested objects
      return data.map(item => ({
        ...item,
        // Explicitly handle nested objects, ensuring they match the expected structure
        kpi_smart_types: item.kpi_smart_types ? (Array.isArray(item.kpi_smart_types) ? item.kpi_smart_types[0] : item.kpi_smart_types) : null,
        kpi_smart_focuses: item.kpi_smart_focuses ? (Array.isArray(item.kpi_smart_focuses) ? item.kpi_smart_focuses[0] : item.kpi_smart_focuses) : null,
        kpi_smart_units: item.kpi_smart_units ? (Array.isArray(item.kpi_smart_units) ? item.kpi_smart_units[0] : item.kpi_smart_units) : null,
        // Add other potentially missing top-level properties with default values if necessary
        user_id: item.user_id || '',
        code: item.code || 0,
        kpi_smart_type_id: item.kpi_smart_type_id || '',
        kpi_smart_action_verb_id: item.kpi_smart_action_verb_id || '',
        kpi_smart_focus_id: item.kpi_smart_focus_id || '',
        kpi_smart_unit_id: item.kpi_smart_unit_id || '',
        status: item.status || 'active',
        created_at: item.created_at || new Date().toISOString(),
      })) as KpiSmart[];
    },
    enabled: !!user?.id && !!selectedPillarIdForKpiSmart,
  });

  const { data: pillars, isLoading: isLoadingPillars } = useQuery<Pillar[], Error>({
    queryKey: ['pillarsListForKpiSmartLiberatedForm', user?.id],
    queryFn: async () => {
      if (!user?.id) return [];
      const { data, error } = await supabase
        .from('pillars')
        .select('*')
        .eq('user_id', user.id)
        .order('description', { ascending: true });
      if (error) throw error;
      return data;
    },
    enabled: !!user?.id,
  });

  const { data: allRelevantUsers, isLoading: isLoadingAllRelevantUsers } = useQuery<BasicProfileInfo[], Error>({
    queryKey: ['allRelevantUsersForKpiSmartLiberatedForm', user?.id, selectedCompany?.id],
    queryFn: async () => {
      if (!user?.id || !selectedCompany?.id) return [];

      const userIds = new Set<string>();
      userIds.add(user.id);

      const { data: companyOwner, error: ownerError } = await supabase
        .from('companies')
        .select('user_id')
        .eq('id', selectedCompany.id)
        .single();
      if (ownerError) console.error("Error fetching company owner:", ownerError);
      if (companyOwner?.user_id) userIds.add(companyOwner.user_id);

      const { data: sharedUsers, error: sharedError } = await supabase
        .from('company_shares')
        .select('shared_with_user_id')
        .eq('company_id', selectedCompany.id);
      if (sharedError) console.error("Error fetching shared users:", sharedError);
      sharedUsers?.forEach(su => userIds.add(su.shared_with_user_id));

      const uniqueUserIds = Array.from(userIds);

      if (uniqueUserIds.length === 0) return [];

      const { data: profiles, error: profilesError } = await supabase
        .from('profiles')
        .select('id, first_name, last_name')
        .in('id', uniqueUserIds);
      if (profilesError) throw profilesError;
      return profiles;
    },
    enabled: !!user?.id && !!selectedCompany?.id,
  });

  const { data: kpiSmartFrequencies, isLoading: isLoadingKpiSmartFrequencies } = useQuery<KpiSmartFrequency[], Error>({
    queryKey: ['kpiSmartFrequenciesForKpiSmartLiberatedForm', user?.id],
    queryFn: async () => {
      if (!user?.id) return [];
      const { data, error } = await supabase
        .from('kpi_smart_frequencies')
        .select('*')
        .eq('user_id', user.id)
        .order('description', { ascending: true });
      if (error) throw error;
      return data;
    },
    enabled: !!user?.id,
  });

  const { data: kpiSmartStatuses, isLoading: isLoadingKpiSmartStatuses } = useQuery<KpiSmartStatus[], Error>({
    queryKey: ['kpiSmartStatusesListForLiberatedForm', user?.id],
    queryFn: async () => {
      if (!user?.id) return [];
      const { data, error } = await supabase
        .from('kpi_smart_statuses')
        .select('*')
        .eq('user_id', user.id)
        .order('description', { ascending: true });
      if (error) throw error;
      return data;
    },
    enabled: !!user?.id,
  });

  const relevantUserOptions: MultiSelectOption[] = useMemo(() => {
    return allRelevantUsers?.map(p => ({
      value: p.id,
      label: `${p.first_name || ''} ${p.last_name || ''}`.trim() || `Usuário ${p.id.substring(0, 8)}`
    })) || [];
  }, [allRelevantUsers]);

  const selectedKpiSmart = kpiSmarts?.find(kpi => kpi.id === form.watch('kpi_smart_id'));
  const kpiSmartTypeCode = selectedKpiSmart?.kpi_smart_types?.code;

  const mutationOptions = {
    onSuccess: () => {
      queryClient.invalidateQueries({ queryKey: ['kpiSmartsLiberated', user?.id] });
      showSuccess(`KPI Smart Liberado ${isEditing ? 'atualizado' : 'criado'} com sucesso!`);
      navigate('/ops/shift/kpi-smarts-liberated');
    },
    onError: (error: Error) => {
      showError(`Erro: ${error.message}`);
    },
  };

  const createKpiSmartLiberatedMutation = useMutation({
    mutationFn: async (data: KpiSmartLiberatedFormData) => {
      if (!user?.id) throw new Error("Usuário não autenticado.");
      console.log("Creating KPI Smart Liberated with data:", data);
      const { data: newKpiSmartLiberated, error } = await supabase
        .from('kpi_smarts_liberated')
        .insert({
          kpi_smart_id: data.kpi_smart_id,
          user_id: user.id,
          execution_user_ids: data.execution_user_ids,
          view_user_ids: data.view_user_ids,
          kpi_smart_frequency_id: data.kpi_smart_frequency_id,
          kpi_smart_status_id: data.kpi_smart_status_id,
          pillar_id: data.pillar_id,
          
          logical_comparator: data.logical_comparator,
          base_value: data.base_value,
          target_value: data.target_value,
          deadline_date: data.deadline_date ? format(data.deadline_date, 'yyyy-MM-dd') : null,

          planned_delivery_date: data.planned_delivery_date ? format(data.planned_delivery_date, 'yyyy-MM-dd') : null,
          actual_delivery_date: data.actual_delivery_date ? format(data.actual_delivery_date, 'yyyy-MM-dd') : null,
          progress_percentage: data.progress_percentage,

          planned_frequency: data.planned_frequency,
          planned_executions: data.planned_executions,
          performed_executions: data.performed_executions,

          min_value: data.min_value,
          max_value: data.max_value,
          current_value: data.current_value,
        })
        .select()
        .single();
      if (error) throw error;
      return newKpiSmartLiberated;
    },
    ...mutationOptions,
  });

  const updateKpiSmartLiberatedMutation = useMutation({
    mutationFn: async (data: KpiSmartLiberatedFormData) => {
      if (!kpiSmartLiberatedId) throw new Error("ID do KPI Smart Liberado está faltando.");
      if (!user?.id) throw new Error("Usuário não autenticado.");
      console.log("Updating KPI Smart Liberated with data:", data);
      const { data: updatedKpiSmartLiberatedResult, error } = await supabase
        .from('kpi_smarts_liberated')
        .update({
          kpi_smart_id: data.kpi_smart_id,
          pillar_id: data.pillar_id,
          execution_user_ids: data.execution_user_ids,
          view_user_ids: data.view_user_ids,
          kpi_smart_frequency_id: data.kpi_smart_frequency_id,
          kpi_smart_status_id: data.kpi_smart_status_id,

          logical_comparator: data.logical_comparator,
          base_value: data.base_value,
          target_value: data.target_value,
          deadline_date: data.deadline_date ? format(data.deadline_date, 'yyyy-MM-dd') : null,

          planned_delivery_date: data.planned_delivery_date ? format(data.planned_delivery_date, 'yyyy-MM-dd') : null,
          actual_delivery_date: data.actual_delivery_date ? format(data.actual_delivery_date, 'yyyy-MM-dd') : null,
          progress_percentage: data.progress_percentage,

          planned_frequency: data.planned_frequency,
          planned_executions: data.planned_executions,
          performed_executions: data.performed_executions,

          min_value: data.min_value,
          max_value: data.max_value,
          current_value: data.current_value,
        })
        .eq('id', kpiSmartLiberatedId)
        .eq('user_id', user.id)
        .select()
        .single();
      if (error) throw error;
      return updatedKpiSmartLiberatedResult;
    },
    ...mutationOptions,
  });

  const onSubmit = (data: z.infer<typeof formSchema>) => {
    const payload: KpiSmartLiberatedFormData = {
      kpi_smart_id: data.kpi_smart_id,
      pillar_id: data.pillar_id,
      execution_user_ids: form.getValues('execution_user_ids') || null,
      view_user_ids: form.getValues('view_user_ids') || null,
      kpi_smart_frequency_id: form.getValues('kpi_smart_frequency_id'),
      kpi_smart_status_id: form.getValues('kpi_smart_status_id'),

      logical_comparator: form.getValues('logical_comparator') || null,
      base_value: form.getValues('base_value') || null,
      target_value: form.getValues('target_value') || null,
      deadline_date: form.getValues('deadline_date') || null,

      planned_delivery_date: form.getValues('planned_delivery_date') || null,
      actual_delivery_date: form.getValues('actual_delivery_date') || null,
      progress_percentage: form.getValues('progress_percentage') || null,

      planned_frequency: form.getValues('planned_frequency') || null,
      planned_executions: form.getValues('planned_executions') || null,
      performed_executions: form.getValues('performed_executions') || null,

      min_value: form.getValues('min_value') || null,
      max_value: form.getValues('max_value') || null,
      current_value: form.getValues('current_value') || null,
    };
    if (isEditing) {
      updateKpiSmartLiberatedMutation.mutate(payload);
    } else {
      createKpiSmartLiberatedMutation.mutate(payload);
    }
  };

  const isLoadingForm = createKpiSmartLiberatedMutation.isPending || updateKpiSmartLiberatedMutation.isPending || isLoadingEditingKpiSmartLiberated || isLoadingPillars || isLoadingKpiSmarts || isLoadingKpiSmartStatuses || isLoadingKpiSmartFrequencies || isLoadingAllRelevantUsers;

  if (isEditing && isLoadingEditingKpiSmartLiberated) {
    return <div className="text-center text-muted-foreground">Carregando KPI Smart Liberado...</div>;
  }

  if (isEditing && !editingKpiSmartLiberated && !isLoadingEditingKpiSmartLiberated) {
    return (
      <div className="flex flex-col items-center justify-center min-h-[calc(100vh-10rem)]">
        <Card className="w-full max-w-md bg-card backdrop-blur-md rounded-2xl shadow-lg p-6 text-center border border-border">
          <CardHeader>
            <CardTitle className="text-2xl font-bold text-sollux-red">KPI Smart Liberado não encontrado</CardTitle>
          </CardHeader>
          <CardContent>
            <p className="text-muted-foreground">O KPI Smart Liberado que você está tentando editar não existe ou você não tem permissão.</p>
            <Button onClick={() => navigate('/ops/shift/kpi-smarts-liberated')} className="mt-4 rounded-lg bg-sollux-red hover:bg-sollux-orange">
              Voltar para KPIs Smart Liberados
            </Button>
          </CardContent>
        </Card>
      </div>
    );
  }

  return (
    <div className="space-y-6">
      <Card className="bg-card backdrop-blur-md border border-border shadow-lg rounded-2xl">
        <CardHeader>
          <CardTitle className="text-foreground uppercase font-bold">
            {isEditing ? 'Editar KPI Smart Liberado' : 'Liberar Novo KPI Smart'}
          </CardTitle>
          <CardDescription className="text-lg text-muted-foreground">
            {isEditing ? 'Atualize os detalhes do KPI Smart liberado.' : 'Selecione um KPI Smart para liberá-lo para uso.'}
          </CardDescription>
        </CardHeader>
        <CardContent className="mt-8">
          <Form {...form}>
            <form onSubmit={form.handleSubmit(onSubmit)} className="space-y-4">
              <FormField
                control={form.control}
                name="pillar_id"
                render={({ field }) => (
                  <FormItem>
                    <FormLabel className="text-foreground">Pilar</FormLabel>
                    <Select onValueChange={(value) => {
                      field.onChange(value);
                      setSelectedPillarIdForKpiSmart(value);
                      form.setValue('kpi_smart_id', ''); // Resetar KPI Smart ao mudar o pilar
                    }} value={field.value} disabled={isLoadingPillars || isLoadingForm}>
                      <FormControl>
                        <SelectTrigger className="rounded-lg">
                          <SelectValue placeholder="Selecione um Pilar" />
                        </SelectTrigger>
                      </FormControl>
                      <SelectContent>
                        {isLoadingPillars ? (
                          <SelectItem value="loading-pillars" disabled>Carregando Pilares...</SelectItem>
                        ) : (pillars && pillars.length === 0) ? (
                          <SelectItem value="no-pillars" disabled>Nenhum Pilar cadastrado</SelectItem>
                        ) : (
                          pillars?.map((pillar) => (
                            pillar.id && pillar.id !== '' ? (
                              <SelectItem key={pillar.id} value={pillar.id}>
                                {pillar.description}
                              </SelectItem>
                            ) : null
                          ))
                        )}
                      </SelectContent>
                    </Select>
                    <FormMessage />
                  </FormItem>
                )}
              />
              <FormField
                control={form.control}
                name="kpi_smart_id"
                render={({ field }) => (
                  <FormItem>
                    <FormLabel className="text-foreground">KPI Smart</FormLabel>
                    <Select onValueChange={(value) => {
                      field.onChange(value);
                      // Buscar detalhes do KPI Smart selecionado para preencher os campos condicionais
                      const details = kpiSmarts?.find(k => k.id === value);
                      setSelectedKpiSmartDetails(details || null);
                      // Atualizar o pilar_id no formulário se o KPI Smart selecionado tiver um pilar associado
                      if (details?.pillar_id && form.getValues('pillar_id') !== details.pillar_id) {
                        form.setValue('pillar_id', details.pillar_id);
                        setSelectedPillarIdForKpiSmart(details.pillar_id);
                      }
                    }} value={field.value} disabled={!selectedPillarIdForKpiSmart || isLoadingKpiSmarts || (kpiSmarts && kpiSmarts.length === 0) || isLoadingForm}>
                      <FormControl>
                        <SelectTrigger className="rounded-lg">
                          <SelectValue placeholder="Selecione um KPI Smart" />
                        </SelectTrigger>
                      </FormControl>
                      <SelectContent>
                        {!selectedPillarIdForKpiSmart ? (
                          <SelectItem value="select-pillar" disabled>Selecione um pilar primeiro</SelectItem>
                        ) : isLoadingKpiSmarts ? (
                          <SelectItem value="loading-kpis" disabled>Carregando KPIs Smart...</SelectItem>
                        ) : (kpiSmarts && kpiSmarts.length === 0) ? (
                          <SelectItem value="no-kpis" disabled>Nenhum KPI Smart ativo disponível para este pilar</SelectItem>
                        ) : (
                          kpiSmarts.map((kpi) => (
                            kpi.id && kpi.id !== '' ? (
                              <SelectItem key={kpi.id} value={kpi.id}>
                                {kpi.description}
                              </SelectItem>
                            ) : null
                          ))
                        )}
                      </SelectContent>
                    </Select>
                    <FormMessage />
                  </FormItem>
                )}
              />
              <FormField
                control={form.control}
                name="kpi_smart_frequency_id"
                render={({ field }) => (
                  <FormItem>
                    <FormLabel className="text-foreground">Frequência de Monitoramento</FormLabel>
                    <Select onValueChange={field.onChange} value={field.value} disabled={isLoadingKpiSmartFrequencies || isLoadingForm}>
                      <FormControl>
                        <SelectTrigger className="rounded-lg">
                          <SelectValue placeholder="Selecione a frequência" />
                        </SelectTrigger>
                      </FormControl>
                      <SelectContent>
                        {isLoadingKpiSmartFrequencies ? (
                          <SelectItem value="loading-frequencies" disabled>Carregando Frequências...</SelectItem>
                        ) : (kpiSmartFrequencies && kpiSmartFrequencies.length === 0) ? (
                          <SelectItem value="no-frequencies" disabled>Nenhuma Frequência cadastrada</SelectItem>
                        ) : (
                          kpiSmartFrequencies?.map((frequency) => (
                            frequency.id && frequency.id !== '' ? (
                              <SelectItem key={frequency.id} value={frequency.id}>
                                {frequency.description}
                              </SelectItem>
                            ) : null
                          ))
                        )}
                      </SelectContent>
                    </Select>
                    <FormMessage />
                  </FormItem>
                )}
              />
              <FormField
                control={form.control}
                name="kpi_smart_status_id"
                render={({ field }) => (
                  <FormItem>
                    <FormLabel className="text-foreground">Status do KPI Smart Liberado</FormLabel>
                    <Select onValueChange={field.onChange} value={field.value} disabled={isLoadingKpiSmartStatuses || isLoadingForm}>
                      <FormControl>
                        <SelectTrigger className="rounded-lg">
                          <SelectValue placeholder="Selecione o Status" />
                        </SelectTrigger>
                      </FormControl>
                      <SelectContent>
                        {isLoadingKpiSmartStatuses ? (
                          <SelectItem value="loading-statuses" disabled>Carregando Status...</SelectItem>
                        ) : (kpiSmartStatuses && kpiSmartStatuses.length === 0) ? (
                          <SelectItem value="no-statuses" disabled>Nenhum Status cadastrado</SelectItem>
                        ) : (
                          kpiSmartStatuses?.map((status) => (
                            status.id && status.id !== '' ? (
                              <SelectItem key={status.id} value={status.id}>
                                {status.description}
                              </SelectItem>
                            ) : null
                          ))
                        )}
                      </SelectContent>
                    </Select>
                    <FormMessage />
                  </FormItem>
                )}
              />

              {/* Exibir detalhes do KPI Smart selecionado */}
              {selectedKpiSmartDetails && (
                <Card className="bg-card/50 border border-border shadow-sm rounded-lg p-4">
                  <CardTitle className="text-lg font-bold text-foreground mb-4">Detalhes do KPI Smart Selecionado</CardTitle>
                  <div className="grid grid-cols-1 md:grid-cols-2 gap-4">
                    <div className="flex flex-col">
                      <Label className="text-foreground">Tipo:</Label>
                      <p className="text-muted-foreground">{selectedKpiSmartDetails.kpi_smart_types?.description || 'N/A'}</p>
                    </div>
                    <div className="flex flex-col">
                      <Label className="text-foreground">Foco:</Label>
                      <p className="text-muted-foreground">{selectedKpiSmartDetails.kpi_smart_focuses?.description || 'N/A'}</p>
                    </div>
                    <div className="flex flex-col">
                      <Label className="text-foreground">Unidade:</Label>
                      <p className="text-muted-foreground">{selectedKpiSmartDetails.kpi_smart_units?.description || 'N/A'}</p>
                    </div>
                  </div>
                </Card>
              )}

              {/* Campos Condicionais baseados no kpiSmartTypeCode */}
              {kpiSmartTypeCode === 1 && ( // Quantitativo
                <Card className="bg-card/50 border border-border shadow-sm rounded-lg p-4">
                  <CardTitle className="text-lg font-bold text-foreground mb-4">Configurações Quantitativas</CardTitle>
                  <div className="grid grid-cols-1 md:grid-cols-2 gap-4">
                    <FormField
